-- data/rows/monstre_espece.sql : export déterministe, une instruction par ligne, triée par (id). NE PAS ÉDITER À LA MAIN.
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/amblypyge-noir', 'Amblypyge noir', 'amblypyge-noir', 1, 'A', 'EP2', 2, 2, 'L’Amblypyge Noir est un grand arachnide des marais corrompus atteignant environ 1,15 mètre de long. Son corps aplati est soutenu par de longues pattes fines qui lui permettent de traverser les eaux stagnantes, les racines et les terrains boueux avec une aisance déconcertante. Ses appendices sensoriels, constamment en mouvement, balayent son environnement à la recherche de la moindre vibration ou trace de corruption. Imprégnée de cette magie, la créature se déplace dans un silence presque surnaturel, donnant souvent l’impression qu’elle est apparue de nulle part.
Profondément liée à la magie de la Corruption, l’Amblypyge Noir semble capable de percevoir naturellement les concentrations de brai, les zones souillées et les créatures affectées par cette énergie. Certains explorateurs prétendent même qu’il peut suivre une piste de corruption sur plusieurs kilomètres, comme un prédateur suivant une odeur invisible. Cette affinité lui permet de prospérer dans des environnements que la plupart des autres créatures évitent, faisant de lui l’un des habitants les plus communs des marais.
Bien que généralement solitaire, l’Amblypyge Noir est un chasseur patient et opportuniste. Il préfère attendre qu’une proie s’approche avant de fondre sur elle avec une rapidité surprenante. Ses pinces et ses pattes acérées peuvent immobiliser une victime tandis que la corruption qui imprègne son organisme affaibli progressivement ceux qui restent trop longtemps à son contact.', 'Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 663-906', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/amphilactrus', 'Amphilactrus', 'amphilactrus', 2, 'A', 'EP2', 2, 2, 'L’Amphilactrus est un hybride aquatique qui rappelle beaucoup un mélange entre amphibien et reptile, relié aux magies de Foudre et Eau. Doté d’un corps souple, d’épines dorsales mobiles et d’une peau luisante, il excelle dans la nage et les attaques éclairs sous-marines. Il vit principalement en couple dans les lacs, les mers ou les mangroves reculées, où il défend farouchement son territoire. Son tempérament sauvage le rend méfiant, mais il est étonnamment joueur et docile envers ceux qui possèdent les mêmes magies que lui ou quand il pleut.
Sa peau doit impérativement rester humide : au sec, elle se craquèle, vire au gris, puis meurt lentement. L’Amphilacrus change de couleur selon son environnement et son état : plus clair s’il naît en eaux chaudes, plus foncé en eaux froides, turquoise s’il vient d’un étang (cas rare), et rose chez les femelles en chaleur.', 'Mer, Océan, Lac, Plage', NULL, 'monstres', 'Bestiaire 2.0 › lignes 910-971', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/archidemon', 'Archidémon', 'archidemon', 3, 'A', 'EP1-10', 1, 10, 'L''Archidémon est la forme ultime de la corruption d''un Majin. Lorsqu''un Majin est exposé trop longtemps au Nuage de Kcirevam, son corps, son esprit et son âme finissent par céder à cette substance démoniaque jusqu''à ne plus laisser subsister la moindre trace de son ancienne identité. Devenu une incarnation vivante du Nuage, il rejoint les rangs des plus redoutables démons connus.
D''une puissance physique colossale, l''Archidémon conserve l''intégralité des magies qu''il maîtrisait avant sa transformation, tout en les utilisant avec une maîtrise décuplée. Véritable prédateur, il ne cherche pas simplement à vaincre ses adversaires : il prend plaisir à les faire souffrir, les traque sans relâche et n''accorde aucune importance à l''honneur ou au fair-play. Son apparence est à l''image de sa nature. Son corps massif à la peau rouge est marqué par un crâne démoniaque au sourire figé, dont les expressions dérangeantes semblent défier toute logique. Ses longues griffes recourbées, ses imposantes cornes, sa queue épaissie et de grandes ailes apparaissent.
Le corps d''un Archidémon produit en permanence un épais nuage de Kcirevam qui s''échappe de chacune de ses ouvertures et s''intensifie au fil du combat. Cette concentration reste insuffisante pour transformer d''autres êtres en démons, mais elle constitue pour lui une source de puissance inépuisable. Plus l''affrontement se prolonge, plus le Nuage envahit les environs et nourrit ses capacités.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 975-1428', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-beige', 'Blob beige', 'blob-beige', 4, 'B', 'EP1', 1, 1, 'Le Blob beige se retrouve notamment dans les plaines là où la lumière pointe le plus fort et le plus longtemps, sa chair brillante est de grande valeur car primordiale dans les fioles blanches.', 'Plaine, Plateau, Pilier de lumière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 1435-1677', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-blanc', 'Blob blanc', 'blob-blanc', 5, 'B', 'EP1', 1, 1, 'Ce Blob transparent est un blob aussi rare que son cousin rose, c''est un blob qui apprécie les lieux où se trouvait les failles temporelles et qui sont désormais fermées. Sa chair est utile pour la surpuissante potion qui permet d''être invulnérable à la magie mais qui empêche d''utiliser la magie.', 'Faille temporelle', NULL, 'monstres', 'Bestiaire 2.0 › lignes 1681-1923', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-bleu', 'Blob bleu', 'blob-bleu', 6, 'B', 'EP1', 1, 1, 'Le Blob bleu est apprécié pour sa belle couleur, on le retrouve près des lacs ou de la mer. Sa chair bleue est indispensable pour la fiole bleue qui redonne chakra. Sa gelée est également un terrain idéal pour la pousse de certaines plantes liées à l’eau comme par exemple le prunier.', 'Plage, Lac, Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 1927-2169', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-bordeaux', 'Blob bordeaux', 'blob-bordeaux', 7, 'B', 'EP1', 1, 1, 'Ce Blob de couleur bordeau, qu''on retrouve notamment dans les zones où le sang a coulé, possède sa chair coagulante accelère naturellement la cicatrisation. Elle est donc utilisée dans des Fioles de régénération.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 2173-2415', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-brun', 'Blob brun', 'blob-brun', 8, 'B', 'EP1', 1, 1, 'Le blob brun se localise dans les montagnes principalement, sa chair est partiellement protéger par une coque de terre qui sens bon et est délicieuse en bouche, sa chair est utilisé pour faire une potion qui renforce la dureté de la peau temporairement.', 'Montagne, Caverne, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 2419-2661', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-cyan', 'Blob cyan', 'blob-cyan', 9, 'B', 'EP1', 1, 1, 'Le Blob Menthe est de couleur cyan qui est là où le froid règne en maître, il est facilement reconnaissable par sa couleur et son odeur très agréable. Sa chair est principalement utilisée pour faire des fioles de résistance magique ou de protection contre la glace.', 'Montagne, Zone froide', NULL, 'monstres', 'Bestiaire 2.0 › lignes 2665-2907', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-jaune', 'Blob jaune', 'blob-jaune', 10, 'B', 'EP1', 1, 1, 'Le blob jaune, qui est associé au citron et à la foudre, se trouve dans les zones où la foudre tombe, sa chair jaune acide en bouche est lié à la barrière et permet de fabriquer la fiole jaune.', 'Zone de foudre, Plateau, Plaine', NULL, 'monstres', 'Bestiaire 2.0 › lignes 2911-3153', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-mauve', 'Blob mauve', 'blob-mauve', 11, 'B', 'EP1', 1, 1, 'Le Blob mauve est un blob qu''on retrouve notamment dans les grottes, sa chair sombre sert d''ingrédient de base pour les fioles mauves.', 'Caverne, Zone sombre, Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 3155-3397', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-metallique', 'Blob métallique', 'blob-metallique', 12, 'B', 'EP1-10', 1, 10, 'Le Blob Métallique est une étrange créature aux origines inconnues. Les circonstances exactes de sa création demeurent inconnues, mais la créature semble avoir assimilé quatre magies : Feu, Terre, Nécromancie et Foudre. Son corps entièrement constitué de métal fondu conserve pourtant une forme mouvante, comme une masse visqueuse capable de se déformer à volonté. Cette combinaison improbable de magies lui confère de nombreuses résistances et immunités.
Il existe dix variétés de Blob Métallique, chacune correspondant à un métal différent et possédant un niveau de puissance qui lui est propre. Chaque métal réagit différemment aux attaques physiques. Les Blobs sont capables d''effectuer de grands bonds pour atteindre leurs proies ou surprendre leurs adversaires, tandis que les spécimens les plus puissants peuvent même se diviser en plusieurs masses lorsqu’ils sont suffisamment menacés.
La nature de leur corps leur procure une protection naturelle contre de nombreux dangers, mais elle constitue également leur principale faiblesse. Le métal de leur corps réagit particulièrement mal à l’eau et au feu. Malgré cela, chaque variété possède ses propres propriétés métalliques, et connaître la composition exacte d’un Blob avant de l’affronter peut faire toute la différence entre une victoire rapide et un combat désastreux.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 3403-3807', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-noir', 'Blob noir', 'blob-noir', 13, 'B', 'EP1', 1, 1, 'Ce Blob est de couleur noire marbrée de teintes de gris asphalte. On retrouve principalement cette créature dans les marécages ou autre zones où la corruption a polluée certaines terres. Sa chair émet une forte quantité de corruption, il est donc très déconseillé de le toucher à main nues sous peine de graves atteintes au lobe chakratique.', 'Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 3809-4054', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-rose', 'Blob rose', 'blob-rose', 16, 'B', 'EP1', 1, 1, 'Ce Blob d''un rose remarquable est un blob très rare qui apprécie les lieux où le Temps et l''Espace sont déformés. Sa chair a une grande valeur car elle est utile pour la Fiole de Rappel et aussi la Fiole de Célérité.', 'Faille temporelle', NULL, 'monstres', 'Bestiaire 2.0 › lignes 4549-4791', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-rouge', 'Blob rouge', 'blob-rouge', 15, 'B', 'EP1', 1, 1, 'Une créature de taille et de couleur variables. Sa gelée est un ingrédient primordial pour les potions. Il existe deux variétés par espèces de blob, un qui correspond au fruit qu''il représente et une autre qui correspond à l''élément associé.
Le blob rouge qu''on retrouve notamment dans les zones où le sang a coulé, sa chair cicatrise naturellement les plaies et redonne des forces, elle est donc utilisé pour les fioles de soin communément appelé fioles rouges. Sa gelée est également un terrain idéal pour la pousse de certaines plantes liées au feu comme par exemple le fraisier. Plus un blob est vieux, plus les plantes vont pousser sur son corps, on peut juger de l’âge d’un blob rien qu’avec ce paramètre.', 'Désert, Plaine, Volcan, Bosquet', NULL, 'monstres', 'Bestiaire 2.0 › lignes 4302-4545', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-royale', 'Blob royale', 'blob-royale', 17, 'B', 'EP1-10', 1, 10, 'Le Blob Royal est l’incarnation ultime de la menace gélatineuse. Né de la fusion anarchique de nombreux blobs élémentaires, il règne en maître absolu sur cette étrange espèce. Son corps titanesque est une masse informe et changeante, où se mélangent couleurs, textures et fragments des essences qui le composent. Ses mouvements font vibrer le sol, et chaque pulsation de sa chair visqueuse est accompagnée d’un son étouffé et sinistre.
L’apparition du Blob Royal est toujours un mauvais présage. Là où il se dresse, villes et campagnes sont condamnées à être englouties dans une marée destructrice. C’est quand une population de blobs est trop nombreuse qu’ils commencent à se rassembler en un seul être. Sa taille détermine sa puissance.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 4797-4961', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-transparent', 'Blob transparent', 'blob-transparent', 14, 'B', 'EP1', 1, 1, 'Ce Blob transparent est un blob aussi rare que son cousin rose, c''est un blob qui apprécie les lieux où se trouvait les failles temporelles et qui sont désormais fermées. Sa chair est utile pour la surpuissante potion qui permet d''être invulnérable à la magie mais qui empêche d''utiliser la magie.', 'Faille temporelle', NULL, 'monstres', 'Bestiaire 2.0 › lignes 4058-4300', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-vert', 'Blob vert', 'blob-vert', 18, 'B', 'EP1', 1, 1, 'Le Blob vert apprécie énormément les hauteurs et les plateaux, sa chair très sucrée est indispensable pour les fioles vertes mais aussi des médicaments utiles pour lutter contre les problèmes de fatigue chronique.', 'Montagne, île flottante', NULL, 'monstres', 'Bestiaire 2.0 › lignes 4967-5221', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/blob-vert-fonce', 'Blob vert foncé', 'blob-vert-fonce', 19, 'B', 'EP1', 1, 1, 'Ce Blob vert foncé qu''on retrouve notamment dans les cimetières et anciens champs de batailles, a une chair visqueuse est très utile pour les mort-vivants et/ou nécromanciens souhaitant soigner leurs plaies ou celles de leurs invocations.', 'Cimetière, Vallée, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 5227-5473', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/carcalanche', 'Carcalanche', 'carcalanche', 20, 'C', 'EP5', 5, 5, 'Le Carcalanche est un zombi figé par un froid si intense qu’il a momifié sa chair en la cristallisant. Son corps desséché, recouvert d''une peau grise et craquelée, ressemble à du cuir ancien tendu sur des os gelés. Ses yeux ont disparu depuis longtemps, remplacés par deux cavités où persiste une brume blanche et froide. Il crisse à chaque mouvement, comme si ses os rappaient sur de la glace vive.
Ses mains se terminent par de longues griffes entièrement formées de glace compacte, translucides et acérées comme des lames. À chaque entaille, le froid s’infiltre dans la plaie, gelant la chair et ralentissant les mouvements de sa victime. Le Carcalanche ne saigne pas, ne ressent rien, et continue d’avancer même lorsque des morceaux de son corps se fissurent ou se brisent sous l’impact.
Plus inquiétant encore, il est capable d’expulser un souffle de froid mordant, une brume glaciale qui exploite le chakra dans son corps. Son corps ne paye pas de mine mais il est capable d''abîmer une arme qui l’attaque si l''exécution avec cette dernière est très mauvaise. Lent mais implacable, le Carcalanche transforme le champ de bataille en tombe gelée, où chaque pas rapproche un peu plus ses proies d’une immobilité éternelle.', 'Montagne, Neige, Forêt froide, Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 5484-5740', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/casque-brise', 'Casque brisé', 'casque-brise', 21, 'C', 'EP2', 2, 2, 'Le Casque Brisé est une apparition silencieuse, composée d’un vieux casque fendu, ébréché, dont les plaques déformées laissent deviner l’impact qui l’a détruit autrefois. De l’intérieur s’échappe un spectre d’un vert sombre, plus léger et plus discret que ses compagnons. Ses contours sont flous, presque translucides, comme si le fantôme lui-même hésitait entre se manifester ou disparaître. Deux lueurs pâles brillent derrière la visière brisée, donnant l’impression d’yeux en observation perpétuelle.
Comme tous les revenants du Cortège du Passé, il est lié à un fragment d’armure imprégné de mémoire guerrière. Il est l’éclaireur, celui qui voit avant les autres, celui qui repère les mouvements du monde des vivants. Dans ses mains spectrales, il tient une arbalète fantomatique, une arme qui se matérialise uniquement lorsqu’il vise sa proie.
À distance, il observe en silence, immobile, presque invisible dans l’obscurité. Lorsqu’il attaque, son tir est précis et silencieux : un carreau spectral qui traverse l’air sans bruit, capable de blesser la chair par delà sa protection. Le Casque Brisé ne cherche jamais l’affrontement direct. Il signale, il surveille, il tire pour affaiblir, puis se retire dans les ombres. La présence de ce guetteur spectral annonce généralement que le reste du cortège approche… et qu’il est déjà trop tard pour fuir.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 5744-5804', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/cerbere', 'Cerbère', 'cerbere', 22, 'C', 'EP5', 5, 5, 'Gardiens abominables des lieux sacrés, ce canidé à trois tête reste et restera fidèle aux ordres de son maître quel qu''ils soient et ces ordres seront probablement pour récupérer votre tête sur votre cadavre en charpie. Ses trois têtes agissent comme un trio de musiciens, accordé et déterminé à vous détruire. Celle de gauche est la plus agressive et violente, celle de droite, elle, est plus réfléchie et sait utiliser des sorts de quatre éléments différents et enfin celle du centre est l''égide des deux autres à laquelle il ne faut pas s''y frotter. Montrez vous plus intelligents que ce chien infernal et peut-être, vous survivrez.', 'Gardien de porte, forêts, plaines, ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 5809-6034', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/charcabe', 'Charcabé', 'charcabe', 23, 'C', 'EP3', 3, 3, 'Le Charcabé est un non-mort incandescent, né de la fusion impie entre la nécromancie et la magie du feu. Contrairement aux zombis classiques rongés par la putréfaction, sa chair est calcinée jusqu''à ne plus être que du charbon craquelé, noir et rougeoyant. Des veines incandescentes parcourent son corps, comme des coulées de lave sous une croûte volcanique. Ses yeux, d’un rouge vif, brillent d’une lueur malsaine, témoins de la haine ardente qui voue à la vie sous toutes ses formes.
Lié à lui comme une extension de sa propre essence brûlante, il manie un sabre sombre et incandescent dont la lame semble nourrie par le feu qui parcourt son corps. Le Charcabé possède les aptitudes d’un mage rouge, capable de concentrer un sort dans sa main avant de le libérer au moment même où sa lame frappe sa cible.
Fait rare parmi les non-morts, le Charcabé est capable de parler. Sa voix ressemble au crépitement d’un brasier, grave et sinistre, comme si chaque mot était soufflé à travers des braises. Cependant, son vocabulaire reste extrêmement limité, se résumant souvent à des menaces ou des paroles liées à la destruction et à la haine de la vie.', 'Désert, Cimetière, Volcan', NULL, 'monstres', 'Bestiaire 2.0 › lignes 6038-6295', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/cheval-bicorne', 'Cheval Bicorne', 'cheval-bicorne', 24, 'C', 'EP5', 5, 5, 'Le Cheval Bicorne est une créature qui symbolise à lui seul la décadence et la malveillance, Sa robe est de couleur noir et possède une fourrure mauve très développée à la crinière et aux sabots. Cette créature n''accepte d''être chevaucher que par des personnes au cœur sombre et mauvais.

Elle possède deux cornes parfaitement lisses et pointu capables de maudire.', 'Forêt, Bosquet, Plaine', NULL, 'monstres', 'Bestiaire 2.0 › lignes 6299-6484', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/cheval-unicorne', 'Cheval Unicorne', 'cheval-unicorne', 25, 'C', 'EP5', 5, 5, 'Le Cheval Unicorne est une créature qui symbolise à lui seul la pureté et la bienveillance, Sa robe est de couleur blanche et possède une fourrure très développer à la crinière et aux sabots. Cette créature n''accepte d''être chevaucher que par des personnes au cœur pur et bienveillant.

Elle possède une corne spiralée pointu très tranchante qui est capable d''aveugler.', 'Forêt, Bosquet, Plaine', NULL, 'monstres', 'Bestiaire 2.0 › lignes 6490-6674', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/collecteur', 'Collecteur', 'collecteur', 26, 'C', 'EP2 - 6', 2, 6, 'Le Collecteur est une abomination, une créature terrifiante née des forces combinées de la Terre et de la Nécromancie. Son corps serpentin est constitué de centaines de cadavres fusionnés, formant une ossature grotesque qui semble bouger en permanence, comme si les âmes qui le composent cherchaient encore à fuir.
Il commence toujours par être petit au début de son existence, environ 1 mètre de long mais plus il trouve des cadavres, plus il va grossir pour atteindre un colossal 9 mètres de long.
On retrouve le Collecteur dans les immenses champs de bataille abandonnés et grandes ruines, là où les corps n’ont pas été inhumés. Il semble attiré par la souffrance collective, émergeant des charniers pour errer à la recherche de nouveaux cadavres à assimiler. Beaucoup racontent qu’il serait une créature qui viendrait punir ceux qui ne prennent pas le temps de respecter les morts, mais il détruit tellement de choses sur son passage que ce genre de réflexion se fait une fois qu’il est vaincu.', 'Ruines, Champ de bataille, Terre désolé', NULL, 'monstres', 'Bestiaire 2.0 › lignes 6680-7018', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/corbeau-agressif', 'Corbeau agressif', 'corbeau-agressif', 27, 'C', 'EP2', 2, 2, 'Le Corbeau Agressif est un volatile aussi étrange que redouté. Il se distingue immédiatement par ses trois pattes et ses trois yeux, tous d’un rouge orangé incandescent. Son plumage, noir profond à la base, se teinte progressivement d’un rouge feu vers les extrémités, comme si ses ailes étaient marquées par une braise éternelle. Les spécimens les plus âgés portent un collier orné de trois talismans rouges en forme de griffe, dont l’origine demeure inconnue ; certains pensent qu’il s’agit d’un don d’un maître invisible ou d’une entité extérieure liée à leur existence.
Attiré de manière obsessionnelle par tout ce qui brille, le Corbeau Agressif est un fléau pour les aventuriers bien équipés. Bijoux, pièces, armes décorées ou simples objets polis deviennent la cible de ses larcins audacieux. Si l’on résiste à ses tentatives de vol, ce fourbe peut littéralement s’embraser, enveloppant ses plumes d’une flamme ardente et cherchant à enflammer sa victime avant de récupérer son butin. Sa ruse est égale à son agressivité, et il préfère toujours dépouiller une cible affaiblie.
Certains majins vénère pourtant ce volatile, symbole de sagesse et d’équilibre. Ce respect semble réciproque : les Corbeaux Agressifs ne pillent jamais les enfants de Kcirevam. Pour le reste des Maverickiens, cependant, leur apparition est un mauvais présage, souvent associé à la perte matérielle imminente.', 'Plaine, ville, champs', NULL, 'monstres', 'Bestiaire 2.0 › lignes 7024-7209', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/crieur-osseux', 'Crieur osseux', 'crieur-osseux', 28, 'C', 'EP3', 3, 3, 'Il s''agit d''un squelette à la mâchoire inférieure manquante mais qui semble être capable de pousser de formidable cri. D''après des légendes, ce sont des serviteurs de la Déesse du Vent mais dont la mission est obscure.
Ces ossements très élancés dont les membres semblent tenir à la force du vent sont capables d''utiliser la magie du vent à leur avantage pour augmenter leur vitesse ou pousser des cris encore plus fort.', 'Montagne, île flottante, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 7211-7466', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/criquet-thaumivore', 'Criquet Thaumivore', 'criquet-thaumivore', 29, 'C', 'EP2', 2, 2, 'Le Criquet Thaumivore est un insecte de grande taille, atteignant en moyenne 50 centimètres de long, reconnaissable à son corps élancé et à ses pattes arrière puissantes, capables de bonds impressionnants. Sa carapace chitineuse présente des reflets ternes parcourus de veines blanches. Ses mandibules, larges et dentelées, sont spécialement adaptées pour broyer des tissus imprégnés de chakra.
Prédateur spécialisé, le Criquet Thaumivore se nourrit presque exclusivement de matière magique vivante, ce qui en fait l’ennemi naturel de nombreuses créatures végétales chakratiques. Il est notamment le principal prédateur des Herbes Folles, dont il raffole pour leur chair à la fois végétale et saturée de chakra. Lorsqu’il mord une proie, sa morsure est capable d’aspirer le chakra circulant dans le corps de sa victime, affaiblissant rapidement les êtres magiques ou les lanceurs de sorts.
L’énergie ainsi absorbée n’est pas dissipée immédiatement : le criquet peut la cumuler dans son corps, ce qui le rend progressivement plus rapide, plus fort et plus difficile à atteindre. Lorsqu’il atteint une surcharge, il libère brutalement cette énergie sous la forme d’une attaque concentrée, souvent un bond dévastateur. Naturellement peu agressif, le Criquet Thaumivore évite les affrontements inutiles. Cependant, lorsqu’il est privé trop longtemps de végétaux magiques, il entre dans un état de frénésie instable, devenant imprévisible et capable d’attaquer des proies bien plus grandes que lui, y compris des humanoïdes.', 'Plaine, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 7470-7670', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/cuirasse-abimee', 'Cuirasse abîmée', 'cuirasse-abimee', 30, 'C', 'EP2', 2, 2, 'La Cuirasse Abîmée est un fantôme étrange : un morceau d’armure rouillé, écailleux et prêt à s’effondrer, porté par un spectre humanoïde d’un vert sombre. Le fantôme, sans visage ni traits distincts, enveloppe la cuirasse comme une silhouette brumeuse, avançant avec lenteur et une présence lourde qui semble alourdir l’air autour de lui. Sa cuirasse et les fragments d’armures qui la composent font son identité.
Cette créature fait partie du Cortège du Passé, un groupe de revenants unis par une même essence spectrale, chacun lié à un fragment d’armure différent. Là où d’autres membres du cortège sont rapides, tranchants ou imprévisibles, la Cuirasse Abîmée se distingue par son aspect massif et son endurance surnaturelle, vestige probable d’un soldat tombé dont l’âme demeure prisonnière de l’acier brisé.
En combat, son rôle est simple et implacable : encaisser, bloquer, retenir. Elle se place volontairement entre ses ennemis et le reste du cortège, absorbant les coups et immobilisant ses adversaires pour offrir à ses compagnons l’occasion de frapper. Muette, obstinée, elle semble guidée par une volonté fantôme qui rejoue inlassablement un devoir oublié.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 7672-7732', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/darvask', 'Darvask', 'darvask', 31, 'D', 'EP3', 3, 3, 'Le Darvask est un immense lézard bipède, massif et primitif, originaire des marais profonds et des cavernes noyées du monde. Sa silhouette est immédiatement reconnaissable : un corps trapu, une queue longue servant de balancier, de puissantes pattes terminées par des serres en croissant, et une gueule longue garnie de rangées de dents acérées. Sa peau écailleuse, striée de plaques osseuses, témoigne de son adaptation à des environnements hostiles et saturés d’humidité.
Il en existe deux variétés distinctes, discernables à la couleur de leurs écailles :
* Les Darvasks des cavernes, d’un gris terne, se nourrissent essentiellement de poissons. Leur odorat fin et leur vision adaptée au clair-obscur en font des prédateurs précis, silencieux et rapides malgré leur taille.

* Les Darvasks des marais, d’un vert profond, se nourrissent essentiellement de fruits, racines et plantes charnues. Leur température corporelle légèrement plus élevée leur permet d’évoluer dans les zones humides et stagnantes sans ralentissement, et leurs larges pieds leur offrent une stabilité exceptionnelle dans la vase.
À l’origine, les Darvasks étaient entièrement sauvages, agressifs et difficiles à approcher. Les Elfes noirs furent les premiers à percevoir leur potentiel stratégique comme monture de guerre. Leur domestication demanda des décennies : enlèvements de jeunes, dressage brutal, sélection des individus les plus dociles et reproduction contrôlée.
Avec le temps, cette lignée apprivoisée a évolué physiquement sous l’influence de l’élevage sélectif : dos plus large et légèrement arqué, capable de supporter un cavalier en armure et son équipement, masse musculaire accrue, notamment au niveau des cuisses et des épaules, posture plus stable, adaptée au port de charges lourdes, comportement plus réactif aux ordres et capable de synchronisation avec un cavalier. Il n’est pas rare aujourd’hui de voir des Darvasks utilisés pour tirer les chariots où même pour se déplacer.', 'Marais, Cavernes, Montagnes, Souterrains', NULL, 'monstres', 'Bestiaire 2.0 › lignes 7738-7924', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-la-foudre', 'Élémentaire de la Foudre', 'elementaire-de-la-foudre', 32, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de la Foudre prend la forme d’une silhouette humanoïde étrange, entièrement constituée de milliers de fils métalliques entrelacés. Ces filaments s’enroulent, se tordent et se réassemblent sans cesse pour maintenir une forme stable, tandis qu’une électricité jaune intense parcourt continuellement son corps. Cette énergie est si abondante qu’elle semble former une seconde couche autour de lui.
Sa vitesse est l’une de ses caractéristiques les plus notables. Ses déplacements ressemblent davantage à des éclairs qu’à une course réelle, et ses mouvements sont souvent si rapides qu’ils paraissent saccadés aux yeux de ses adversaires. Mais sa véritable particularité réside dans la nature de ses attaques : qu’elles soient physiques ou magiques, celles-ci perdent une partie de leur puissance directe, n’infligeant qu’environ la moitié de leur force initiale à leur cible principale.
Cependant, cette perte n’est qu’une illusion. L’énergie restante est redistribuée sous forme de chaînes électriques vers toute cible située à proximité. Si un ennemi se trouve à trois mètres ou moins de l’impact initial, il reçoit à son tour une décharge qui peut ensuite se propager vers d’autres cibles proches, créant une cascade destructrice à travers les rangs ennemis. Une même cible ne peut toutefois être frappée qu’une seule fois par une attaque donnée, empêchant toute boucle infinie.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 7933-8063', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-la-glace', 'Élémentaire de la Glace', 'elementaire-de-la-glace', 33, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de Glace est un cas particulier en son genre, car il ne se manifeste jamais sous une forme unique, mais sous la forme de deux créatures indissociables. Ensemble, elles forment un tout instable, mêlant force brute et maîtrise magique, destruction physique et annihilation magique.
La première entité est de neige. Il prend la forme d’un gigantesque amas de neige compacte, vaguement humanoïde, évoquant un colossal bonhomme de neige difforme. Massif et lent, il combat exclusivement par la force physique, écrasant, projetant et bloquant ses ennemis avec une puissance écrasante. Sa défense physique est exceptionnelle, capable d’absorber des coups qui pulvériseraient toute autre créature.
La seconde entité est de cristal. Plus petit mais plus dangereux d’une certaine façon, il est constitué d’un assemblage de cristaux de glace tranchants, en perpétuel mouvement. Doté d’une intelligence froide et calculatrice, il est capable de manipuler la magie de la glace pour attaquer, entraver et détruire ses adversaires à distance, transformant le champ de bataille en piège gelé. Il possède également une défense magique impressionnante.', 'Montagne, Lieu froid', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8067-8253', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-la-lumiere', 'Élémentaire de la Lumière', 'elementaire-de-la-lumiere', 34, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de la Lumière prend l’apparence d’une silhouette féminine faite de cristal beige lumineux, rappelant fortement l’image d’une version adulte de la déesse de la Lumière. Son corps semble sculpté dans une matière pure et translucide qui diffuse constamment une clarté étrange, son visage ne possède rien d’autre que son regard, un regard de femme dure. Dans son dos se déploient de longues ailes constituées de filaments solides, semblables à des rayons figés, bien plus matérielles que celles de la divinité qu’elle évoque. Son simple regard est difficile à soutenir, tant sa présence donne une impression de grandeur écrasante.
À son arrivée sur le champ de bataille, l’Élémentaire invoque immédiatement un Grand Soleil. Sous cette lumière absolue, sa puissance augmente considérablement : sa vitesse, ses capacités lumineuses et sa présence deviennent plus oppressantes, comme si elle absorbait directement l’énergie solaire pour renforcer sa forme. L’air devient plus chaud, les ombres disparaissent et le terrain lui-même semble baigner dans une clarté trop parfaite.
Sa particularité la plus frustrante réside dans ses champs de force adaptatifs. Lorsqu’elle subit une attaque alors qu’aucune protection ne l’entoure, un bouclier lumineux apparaît instantanément autour d’elle. Ce champ de force possède une résistance exactement égale à la quantité de dégâts de l’attaque précédente, obligeant ses adversaires à constamment revoir leur façon de frapper. Plus les coups deviennent puissants, plus les barrières qu’elle génère le deviennent également. Face à elle, la force brute seule ne suffit pas : il faut comprendre son rythme, sous peine de voir ses assauts totalement contestés.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8257-8385', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-la-necromancie', 'Élémentaire de la Nécromancie', 'elementaire-de-la-necromancie', 35, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de la Nécromancie est une créature profondément dérangeante, bien loin des formes humanoïdes que prennent la plupart des autres élémentaires. Son corps ressemble à une masse recroquevillée en position fœtale, semblable à un immense haricot difforme composé d’os entrelacés, de matière nécrosée et de poison coagulé. En son centre palpite un cœur noirâtre imprégné d’énergie nécromantique, battant lentement comme une chose encore vivante. Sa simple présence refroidit l’air et donne la sensation que la vie elle-même se retire lentement des environs.
Contrairement aux autres élémentaires, il ne combat presque jamais directement. Dès qu’un affrontement commence, il s’enferme derrière une cage d’os impénétrable, une structure monstrueuse qui se reforme sans cesse et semble impossible à briser par la force brute. Depuis ce sanctuaire macabre, il observe ses ennemis et laisse d’autres combattre à sa place. Son corps demeure presque immobile, comme une reine monstrueuse protégée par son armée.
Sa véritable menace réside dans sa capacité à invoquer des non-morts. Il peut maintenir jusqu’à quatre invocations simultanément, choisies parmi tout le répertoire auquel sa puissance lui donne accès. Lorsqu’une créature invoquée est détruite, une nouvelle apparaît presque immédiatement pour prendre sa place. Cependant, cette puissance possède une faille : la destruction d’une invocation renvoie une partie de son essence vers son maître, et la santé restante de l’invocation au moment de sa mort est directement infligée à l’Élémentaire. Ainsi, vaincre cette entité ne consiste pas à briser sa cage dorée… mais à retourner sa propre armée contre elle-même.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8389-8503', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-la-terre', 'Élémentaire de la Terre', 'elementaire-de-la-terre', 36, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de la Terre est une entité colossale à l’apparence humanoïde, composée de blocs de roche massifs entrelacés par d’épaisses lianes vivantes. Son corps évoque une statue ancienne arrachée au sol lui-même, animée par une force primitive, rappelant la figure du dieu de la terre Dimitri mais beaucoup plus chaotique dans son apparence. Ses mouvements, bien que lourds en apparence, sont soutenus par ses lianes qui ondulent en permanence, lui donnant une fluidité trompeuse.
Contrairement à ce que son aspect laisse penser, il ne se contente pas d’encaisser : il est capable d’attaques rapides et précises, utilisant ses lianes comme des fouets capables de frapper à distance, d’entraver ou de repousser ses adversaires. Sa maîtrise de la magie de la terre lui permet de modifier le terrain à volonté, faisant surgir murs de pierre, racines et piliers pour remodeler entièrement le champ de bataille.
Sa stratégie repose sur le contrôle et l’isolation. Il peut créer un véritable labyrinthe de roches et de lianes, forçant ses ennemis à se disperser et à perdre du temps en tentant de l’atteindre. Pendant cette traque, il harcèle ses cibles à distance avant de les isoler une par une. Lorsqu’un adversaire devient trop dangereux, il peut l’immobiliser brièvement pour engager un affrontement individuel, exploitant sa résistance naturelle pour dominer dans un duel où le terrain lui appartient entièrement.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8507-8636', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-larcane', 'Élémentaire de l’Arcane', 'elementaire-de-larcane', 37, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire d’Arcane possède une apparence presque parfaite, comme une représentation idéalisée d’un être humain à laquelle il manquerait quelque chose d’essentiel. Son corps ressemble à une sculpture brillante gris argenté, lisse et dépourvue du moindre détail superflu. Sans visage, sans expression et sans véritables pieds ni chevilles, il flotte silencieusement au-dessus du sol, comme s’il refusait de suivre les règles physiques imposées au reste du monde.
Sa particularité est sa capacité à entrer en résonance avec le chakra de ses adversaires. Plus une cible possède une réserve importante, plus l’Élémentaire devient dangereux face à elle. Il exploite directement l’énergie de ses ennemis pour renforcer ses attaques, augmentant sa puissance à mesure qu’il ressent une présence magique importante. Les mages, prêtres et autres utilisateurs intensifs du chakra deviennent ainsi ses cibles favorites, leur propre force se transformant progressivement en avantage pour lui.
Mais sa capacité la plus inquiétante réside dans son contrôle de l’énergie adverse. Lorsqu’un ennemi utilise son chakra et perd le contrôle de sa propre magie, l’Élémentaire provoque une résonance destructrice où une partie de l’énergie consommée se retourne contre son utilisateur et le blesse. Il est également capable de forcer une consommation accrue de chakra, épuisant rapidement ses victimes. Les plus puissants de son espèce poussent cette logique encore plus loin : ils peuvent injecter leur propre chakra dans leurs ennemis, nourrissant artificiellement leurs réserves uniquement pour amplifier davantage leur propre puissance. Face à un Élémentaire d’Arcane, disposer d’une immense réserve de chakra cesse d’être un avantage… et devient parfois une condamnation.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8638-8766', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-leau', 'Élémentaire de l’Eau', 'elementaire-de-leau', 38, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de l’Eau se manifeste sous la forme d’une masse liquide difforme rappelant vaguement une silhouette humanoïde monstrueuse. Son corps ne semble jamais totalement stable : ses membres s’étirent, se déforment ou disparaissent avant de se reformer ailleurs, donnant l’impression qu’une vague consciente tente de maintenir une apparence vivante sans jamais réellement y parvenir.
Sa particularité réside dans sa capacité à alterner librement entre les trois états de l’eau : liquide, solide et gazeux. Sous sa forme liquide, il adopte un équilibre entre défense et mobilité, capable d’absorber une partie des impacts tout en gardant une grande souplesse dans ses mouvements. Sous sa forme solide, son corps se transforme en une masse de glace dense et résistante, presque insensible aux dégâts magiques mais plus vulnérable aux attaques physiques. À l’inverse, sa forme gazeuse lui permet de devenir une brume presque intangible, quasi invulnérable aux attaques physiques, mais bien plus sensible aux dégâts magiques.
Le plus dangereux reste toutefois son comportement imprévisible : l’Élémentaire de l’Eau change d’état de manière chaotique et aléatoire, parfois au pire moment pour ses adversaires. Une attaque physique peut traverser une brume une seconde avant de rencontrer une masse de glace la suivante. Il est pratiquement impossible d’anticiper précisément ses réactions, forçant ses ennemis à constamment adapter leur stratégie sous peine de gaspiller leurs efforts contre une forme inadaptée.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8770-8908', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-lespace-temps', 'Élémentaire de l’Espace/Temps', 'elementaire-de-lespace-temps', 39, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de l’Espace/Temps est une vision profondément dérangeante, comme si plusieurs réalités avaient tenté de créer un même être sans parvenir à s’accorder. Son corps humanoïde massif est composé d’un mélange contre nature de matière organique, de structures mécaniques et de longues bandelettes rappelant celles des momies anciennes. Doté de quatre bras et quatre jambes, il possède une silhouette déséquilibrée et pourtant étrangement harmonieuse dans ses mouvements. Ses membres semblent parfois apparaître avec un léger retard, ou bouger avant même que le reste du corps ne les suive, comme si son existence entière souffrait d’un décalage avec la réalité.
Comme toutes les créatures liées à l’Espace/Temps, il maîtrise naturellement les téléportations et les portails, disparaissant d’un endroit pour réapparaître ailleurs sans prévenir. Mais là où les autres exploitent ces pouvoirs comme de simples outils, lui agit directement sur les règles mêmes de la réalité. En effet, il est sensible au dégâts physiques que les tours pairs et invulnérable aux dégâts magiques. Mais c’est l’inverse les tours impairs.
Une autre particularité est son pouvoir d’altération des résultats. Une attaque qui aurait dû réussir peut soudainement manquer sa cible, tandis qu’une action banale pour lui devient anormalement efficace. Un coup destiné à blesser peut frapper une zone vitale ; un sort de contrôle peut durer plus longtemps que prévu ; une défense parfaite peut échouer pour une raison impossible à expliquer. L’Élémentaire ne modifie pas directement les actions : il déforme les probabilités et les conséquences, comme s’il réécrivait discrètement ce qui était censé arriver. Face à lui, même la stratégie la plus parfaite peut soudainement cesser d’avoir du sens.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 8912-9043', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-de-lombre', 'Élémentaire de l’Ombre', 'elementaire-de-lombre', 40, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de l’Ombre est une entité insaisissable, dépourvue de forme fixe, se manifestant d’abord comme un brouillard sombre en perpétuel mouvement. Sa présence est presque imperceptible, une absence de lumière plus qu’une véritable silhouette. Mais dès qu’un intrus pénètre dans son territoire, cette brume se condense, adoptant des formes humanoïdes inquiétantes : des copies imparfaites, sans visage, de ceux qu’elle observe.
Sa capacité la plus troublante est sa faculté à imiter ses ennemis. Il reproduit leur nombre, leurs armes, leur posture et même leurs compétences apparentes, comme s’il capturait leur ombre pour la retourner contre eux. Le champ de bataille devient alors un miroir déformé où les adversaires doivent affronter leurs propres reflets, incapables de distinguer le vrai du faux. Cette imitation n’est pas parfaite dans l’essence, mais elle l’est suffisamment dans la forme pour semer le doute et la confusion.
En combat, tous les doubles invoqués sont intangibles, à l’exception d’un seul, le véritable corps de l’élémentaire. Ce dernier représente son seul et unique point faible, mais à chaque impact, il change instantanément de position en échangeant sa place avec une autre ombre, brouillant totalement les repères. Vaincre un Élémentaire de l’Ombre demande une observation constante et une grande lucidité : frapper au hasard revient à perdre du temps, et dans l’obscurité qu’il contrôle, chaque erreur rapproche un peu plus ses proies de leur propre disparition.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9047-9176', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-du-feu', 'Élémentaire du Feu', 'elementaire-du-feu', 41, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de Feu est une entité immédiatement reconnaissable : une masse de flammes vivantes jaillissant en continu, enveloppant un squelette de roche magmatique incandescent. Son corps semble instable, oscillant entre une silhouette humanoïde et une boule de feu incontrôlable. En son centre, un noyau dense et brûlant maintient sa cohésion, donnant à cette créature une forme tangible au cœur du chaos ardent.
Son comportement est aussi agressif que son élément le suggère. Il attaque par des projections de flammes, des charges embrasées ou des explosions de chaleur pure, transformant le terrain en brasier. Cependant, sa véritable particularité réside dans sa capacité à se diviser sous l’impact. Lorsqu’il subit suffisamment de dégâts, il se scinde en deux entités distinctes, chacune possédant une part de sa santé lors de la division. Ce processus peut se répéter jusqu’à trois divisions, à condition que l’élémentaire dispose encore d’assez de santé pour maintenir son existence.
Cette mécanique rend le combat particulièrement dangereux : plus on le frappe, plus il devient nombreux. Et malgré leur taille réduite, les fragments générés sont tout aussi puissants que la forme originelle, conservant la même intensité de feu et la même agressivité. Ce qui commence comme un affrontement contre une seule créature peut rapidement devenir une lutte contre une nuée d’incarnations ardentes, chacune capable de brûler, exploser et consumer sans distinction.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9180-9305', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-du-sang', 'Élémentaire du Sang', 'elementaire-du-sang', 42, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire de Sang est une entité incarnant la violence viscérale, la montée de l’adrénaline et l’ivresse du combat prolongé. Il se manifeste sous la forme d’un humanoïde entièrement écorché, dont les muscles à vif ondulent sous une peau absente. Le sang ne coule pas de ses chairs exposées : il circule, vibre et pulse comme une énergie vivante, liant chaque fibre musculaire à une volonté unique de destruction.
Son physique est impressionnant et disproportionné, forgé pour la guerre et l’écrasement. Chaque mouvement trahit une puissance brute colossale, dénuée de toute retenue. L’Élémentaire de Sang est insensible à la douleur, ou du moins incapable de la reconnaître comme une faiblesse : blessures, mutilations et fractures ne font qu’alimenter sa frénésie.
Sa particularité la plus redoutable réside dans son évolution permanente en combat. À l’instar d’un golem de chair, il dispose de multiples attributs adaptatifs, mais là où le golem se recompose de manière instable, l’Élémentaire de Sang s’améliore de façon définitive. Plus le combat s’éternise, plus l’excitation monte, plus l’entité gagne en puissance, accumulant ses mutations sans jamais les perdre. Ils les perdra au fur et à mesure du temps sans se battre.
Cette progression mène à sa forme dite “finale” : l’apparition d’une seconde paire de bras parfaitement fonctionnelle, symbole sacré et blasphématoire rappelant directement le Dieu du Sang. Ce stade marque le moment où la créature cesse d’être simplement puissante pour devenir un danger.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9307-9459', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-du-vent', 'Élémentaire du Vent', 'elementaire-du-vent', 43, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire du Vent est une créature presque entièrement dépourvue de matière physique, composée de vents violents, de nuages sombres et de tempêtes en mouvement perpétuel. Son corps n’est jamais réellement fixe : sa silhouette humanoïde se forme puis se déchire au rythme des courants qui le traversent. Au centre de cette masse tourbillonnante se trouve son unique élément tangible : un cœur vert éclatant, semblable à une émeraude lumineuse, suspendu au milieu du cyclone comme l’ancre maintenant son existence.
Sa particularité est qu’il force tous ses adversaires à combattre selon ses règles. Autour de lui se forme un cyclone permanent qui balaie le champ de bataille, arrachant obstacles, débris et protections naturelles. Bien que ce vent n’inflige aucun dégât direct, il rend toute approche extrêmement difficile. L’Élémentaire se place naturellement au centre du terrain, poussant ses ennemis vers les extrémités pendant qu’il reste libre de déchaîner ses nombreux sorts liés au Vent.
S’approcher de lui devient une épreuve en soi. Les ennemis doivent traverser la tornade centrale afin d’atteindre son cœur, mais progresser dans ce chaos demande une grande stabilité ou de réflexe : un mauvais mouvement ralentit fortement l’avancée et empêche toute accélération brutale. Ceux qui perdent leur appui risquent même d’être repoussés en arrière par les vents, les forçant à recommencer leur progression. Plus inquiétant encore, les projectiles et les attaques magiques ne peuvent traverser le cyclone, étant immédiatement emportés ou dispersés avant d’atteindre le centre. Affronter un Élémentaire du Vent ne consiste donc pas seulement à survivre à ses attaques : il faut d’abord parvenir jusqu’à lui.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9464-9599', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/elementaire-du-vide', 'Élémentaire du Vide', 'elementaire-du-vide', 44, 'E', 'EP3, 5, 7', 3, 7, 'L’Élémentaire du Vide prend la forme d’un immense crâne flottant d’environ 1,80 mètre de haut, fissuré et déformé comme s’il avait été arraché à une réalité morte. Sa surface semble incomplète, certaines parties disparaissant dans une obscurité impossible à distinguer. Autour de lui gravitent de petites flammes noires semblables à des trous dans l’air, tandis qu’une énergie silencieuse et oppressante émane de chacune de ses orbites vides. Son existence donne l’impression que le monde autour de lui perd lentement sa cohérence.
Contrairement à d’autres élémentaires plus brutaux, celui du Vide ne cherche pas à écraser directement ses ennemis. Il préfère les affaiblir lentement par une série d’effets imprévisibles et perturbants. Au début de chacun de ses tours, il projette gratuitement une manifestation chaotique sur un adversaire choisi au hasard : une sphère obscure, une flamme vide, une onde de néant ou une distorsion invisible. La cible peut tenter d’esquiver ou de résister à cette attaque, mais même lorsqu’elles sont faibles individuellement, ces altérations deviennent difficiles à supporter sur la durée.
Les effets infligés varient constamment… Le Vide ne détruit pas immédiatement ; il use, désoriente et érode progressivement ses proies jusqu’à ce qu’elles ne puissent plus lutter correctement. Face à lui, le véritable danger n’est pas un coup fatal, mais l’accumulation incessante d’effets négatifs qui transforment peu à peu le combat en descente inévitable vers l’oubli.', 'Ruines, Proche des failles', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9603-9750', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/embrase', 'Embrasé', 'embrase', 45, 'E', 'EP4', 4, 4, 'Ce sont des condamnés à mort par le Temple du Feu pour des fautes graves envers le Temple, Séraphin ou même en dehors, ils sont purifiés dans la chambre des cendres par un feu particulier dont seul le Haut Prêtre du Feu à le secret. Toute la chair est brûlé, ne reste qu''une partie du squelette et les cendres, par une formule étrange, le squelette se relève, les parties manquante sont caché par les cendres et ils sont jetés dans le désert Doré près du Volcan, condamné à errer le temps qu''ils doivent purger. Là où il y a un embrasé, il y a eu le passage de prêtres du feu.', 'Volcan, Désert, Terres brûlées, Ruines brûlées', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9754-9937', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/epee-rouillee', 'Épée rouillée', 'epee-rouillee', 46, 'E', 'EP2', 2, 2, 'L’Épée Rouillée est un revenant glaçant, composé d’une épée à deux mains rongée par l’oxydation, brisée par endroits, mais encore lourde et menaçante. L’arme flotte dans l’air, tenue par un spectre d’un vert sombre, dont seules de vagues silhouettes de mains éthérées se dessinent lorsqu’il l’élève. Son aura est plus vive et plus agressive que celle des autres membres du cortège, comme si le fantôme qui l’habite avait conservé l’instinct de frapper avant toute chose.
Comme les autres fragments hantés du Cortège du Passé, l’Épée Rouillée est un vestige animé d’un guerrier oublié, mais contrairement aux fragments d’armures, il n’a aucun rôle défensif ou de soutien. Il est le bras armé du groupe aux côtés de la hallebarde amochée, l’ombre meurtrière qui avance en premier. La lame tremble légèrement, non sous l’effet du vent, mais sous celui d’une rage fantomatique qui semble repousser la mort elle-même.
Lorsqu’un intrus pénètre sur leur territoire, l’Épée Rouillée est le premier à fondre sur lui dans un mouvement brusque, presque animal. Sa lame, bien que émoussée et abîmée, traverse chair et armure comme si elles étaient intangibles. Il ne parle pas, ne prévient pas, et ne montre aucune hésitation : il attaque, guidé par un devoir spectral ou par la simple habitude meurtrière d’une vie passée. Sa présence est un avertissement clair : le Cortège ne tolère aucun vivant sur son chemin.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 9941-10001', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/fourbraise', 'Fourbraise', 'fourbraise', 47, 'F', 'EP1', 1, 1, 'Le Fourbraise est une grosse fourmi rouge mesurant en moyenne 80 centimètres. Elle domine les régions chaudes, où ses colonies peuvent s''étendre sur de vastes territoires. Son corps robuste et son affiliation à la magie du Feu en font déjà un adversaire correct, mais ce sont surtout ses mandibules qui constituent ses armes principales : capables de saisir, broyer et déchiqueter leurs victimes avec une efficacité redoutable.
Lorsqu''elle se sent menacée, la Fourbraise est également capable de souffler des flammes, transformant son corps en véritable arme incendiaire. Elle privilégie cependant le combat en groupe et agit toujours en coordination avec les autres membres de sa colonie. Plusieurs Fourbraises peuvent ainsi encercler un ennemi, se relayer pour l''attaquer avec leurs mandibules et couvrir leurs mouvements de jets de flammes, rendant leur nombre bien plus dangereux que ne le laisserait penser la force d''un individu isolé.
Il existe toutefois une caste particulière appelée Fourbraise Chevaleresse, considérée comme la version la plus redoutable de l''espèce. Contrairement aux autres Fourbraises, elle est capable d''affronter seule une menace importante et semble parfaitement adaptée aux combats individuels. Sa puissance et sa résistance sont telles qu''elle peut tenir tête à des adversaires qui auraient normalement nécessité l''intervention de toute une colonie.', 'Désert, plaine sèche, canyon, zone chaude', NULL, 'monstres', 'Bestiaire 2.0 › lignes 10007-10222', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/fulgurame', 'Fulgurâme', 'fulgurame', 48, 'F', 'EP3', 3, 3, 'Le Fulgurâme est un revenant né d’une catastrophe magique. Autrefois soldat, il fut frappé par une décharge d’énergie si violente que son corps fut consumé sur place. Pourtant, son âme refusa de disparaître et se lia à l’orage qui l’avait détruit. Il ne reste aujourd’hui de lui qu’un squelette mêlé de fragments de métal, comme soudés par la foudre elle-même. Entre ses os circulent des arcs électriques instables qui crépitent en permanence, illuminant sa carcasse d’éclairs jaunes.
Cette énergie résiduelle est la source de sa puissance. Armé d’une lance métallique, il canalise l’électricité parcourant son corps pour frapper ses adversaires avec une violence fulgurante. Chaque coup peut libérer un éclair qui va ignorer les défenses adverses.
Habité par une haine profonde envers la vie, le Fulgurâme considère son existence comme une malédiction qu’il doit partager. Il utilise sans retenue la puissance qui l’a tué, cherchant à infliger aux autres la même fin tragique.', 'Zone de foudre, Plateau, Plaine', NULL, 'monstres', 'Bestiaire 2.0 › lignes 10224-10470', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/gants-usages', 'Gants usagés', 'gants-usages', 49, 'G', 'EP2', 2, 2, 'Les Gants Usagés sont une manifestation spectrale inquiétante : deux gantelets usés, cabossés et ternis, suspendus dans l’air par un revenant d’un vert sombre, semblable à une vapeur condensée. Les bras et le corps diffus permettent de correctement le repérer.
Comme les autres morceaux, ils appartiennent au Cortège du Passé, ces fragments d’armure hantés marchant ensemble comme les débris d’une armée oubliée. Là où certains membres du cortège frappent ou bloquent, les Gants Usagés incarnent l’étrangeté et l’imprévisibilité : autrefois portés par un mage, ou peut-être simplement imbibés de résidus arcaniques, ils sont devenus le canal d’une magie chaotique que même leur spectre ne semble pas contrôler totalement.
En combat, les gants s’animent soudain, exécutant des gestes rapides et précis pour libérer des sorts d’attaques ou d’entraves. Leur danger réside autant dans leur pouvoir que dans leur imprévisibilité, car chaque incantation fantomatique peut être aussi dévastatrice qu’inattendue. L’aura orange, qu’émane parfois le revenant, traduit une utilisation du Potentiel Illimité mais non complète.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 10483-10543', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/gardien-du-passe', 'Gardien du Passé', 'gardien-du-passe', 50, 'G', 'EP4', 4, 4, 'Le Gardien du Passé est la forme ultime du Cortège, l’incarnation parfaite de toutes leurs âmes réunies. Lorsque la menace devient trop grande pour que les fragments d’armure agissent séparément, leurs essences se rassemblent et fusionnent en un seul être : un colosse spectral portant l’intégralité des pièces de l’armure ancienne, accompagné des 2 armes. Il ne ressemble plus à un assemblage hétéroclite, mais à un chevalier complet, massif, imposant, et irradiant une lueur vert sombre presque suffocante.
Doté de l’intellect combiné des six spectres, le Gardien possède une conscience tactique redoutable, capable d’anticiper les mouvements ennemis comme s’il observait simultanément sous plusieurs angles. Il manie l’épée rouillée, la hallebarde amochée, l’arbalète fantomatique, la dague fantomatique ainsi que la griffe fantomatique qu’il manie avec aisance, changeant d’arme au gré des besoins, et dispose des talents martiaux, furtifs et magiques des autres membres du Cortège. Sa présence fait chuter la température, et chaque pas soulève un souffle glacé, comme si le passé lui-même se refermait sur les intrus.
Lorsque le Gardien apparaît, ce n’est plus une simple défense : c’est un verdict. Il est le dernier rempart, le vent glacial qui annonce le trépas. Tant qu’il subsiste, il porte la force combinée de ses fragments, et ne se dissipe qu’une fois la menace anéantie ou son territoire hors de danger. Ceux qui croisent son chemin comprennent immédiatement qu’ils ne font plus face à un fantôme… mais au passé tout entier qui refuse d’être profané.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 10547-10663', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/garrestre', 'Garrestre', 'garrestre', 51, 'G', 'EP7', 7, 7, 'Le Garrestre est une créature bipède colossale née de la colère brute de la forêt. Haut de 2,20 mètres pour les plus jeunes jusqu’à 3,5 mètres pour les plus anciens, il possède un corps massif couvert d’une peau épaisse aux teintes vert sombre et brun terreux, mêlée d’excroissances rappelant l’écorce, la pierre et les racines. Son allure évoque une fusion imparfaite entre bête, sol forestier et force élémentaire, comme si la forêt elle-même avait donné forme à sa rage.
Ces géants herbivores rares incarnent une manifestation vivante de la volonté forestière lorsque l’équilibre est menacé. Il est difficile d’expliquer comment c’est possible mais ils ont une sorte de symbiose avec la forêt, à tel point qu’ils ne peuvent pas vivre en dehors d’une forêt, même si elle est petite. Ils surgissent lors de dévastations majeures, d’incendies, de profanations ou de guerres prolongées sur des terres anciennes.
Malgré leur nature violente, les Garrestres tolèrent — et parfois protègent — les elfes forestiers, qu’ils reconnaissent comme des gardiens légitimes des bois. Dans de rares cas, ils acceptent même de combattre à leurs côtés lors de campagnes militaires défensives, avançant comme des béliers vivants au cœur des lignes ennemies. Les Garrestres qui accompagnent les forces militaires elfes forestiers sont lié au régiment et non plus à la forêt, ce qui fait que ces titans ne sont pas à prendre à la légère, ils défendront leur groupe comme s’il s’agissait d’une forêt.
En combat, le Garrestre fait preuve d’une puissance écrasante. Ses griffes sont capables d’arracher des morceaux de sol, qu’il projette ensuite sous forme de rochers massifs sur ses adversaires. À courte distance, il frappe avec ses poings titanesques, broyant les ennemis dans un déluge de coups lourds. Face à un Garrestre, on ne combat pas une simple créature : on affronte la forêt elle-même, en colère et sans pitié.', 'Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 10669-10821', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/gobelin', 'Gobelin', 'gobelin', 52, 'G', 'EP1', 1, 1, 'Les Gobelins sont des créatures hideuses et rancunières, rancunières de leur aînés : les elfes noirs. Lorsque les elfes dorés ont bannis leurs confrères grâce à l''aide de Mirada, ils ont condamné ces derniers à agoniser dans la corruption pure : Eaunoire a sauvé les exilés de cette mort certaine. Mais malheureusement, l''ex-ambassadeur n''a pas réussi à sauver tout le monde. Des pertes ? Il y en a eu, mais de rares survivants ont su persister mais à un prix... la perte d''un corps à peu près regardable, une peau noircie par la magie noire et surtout, une espérance de vie ridicule d''à peine un an. Pendant des siècles, ces frères oubliés ont vécu dans la pénombre, en se reproduisant comme des lapins dans des cavernes insalubres.
Éventuellement, ces exilés des elfes dorés ont su créer une société primaire régie par ce que l''on appelle un Hobgobelin. Un gobelin particulier qui est capable de vivre une vingtaine d''années et qui, naturellement, mène ses cadets à la bataille.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 10829-10984', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/gobelin-archer', 'Gobelin Archer', 'gobelin-archer', 53, 'G', 'EP1', 1, 1, 'Les Gobelins Archer sont une variante des Gobelins, plus malins que leur confrères qui se contentent d''agiter leur lame grossière. Bien que l''on puisse les considérer comme des lâches, ils n''en restent pas moins dangereux.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 10988-11141', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/gobelin-mage', 'Gobelin Mage', 'gobelin-mage', 54, 'G', 'EP1', 1, 1, 'Les Gobelins Mage sont de loin les plus intelligents de leur espèce. On les retrouvent souvent en tant que conseillés des Hobgobelins ou bien à préparer divers poisons et surtout du brai noir pour les archers. Leur cervelle moins atrophiée que leurs confrères et consœurs compense leur inaptitude au combat au corps-à-corps. Même si ils savent un minimum manier un bâton.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 11147-11315', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-darcane', 'Golem d’arcane', 'golem-darcane', 55, 'G', 'EP9', 9, 9, 'Le Golem d''Arcane est un être que l''on peut considérer comme fantomatique. Son corps éthéré d''une blancheur écarlate flotte au-dessus des lieux chargés d''histoires où les combats entre mages ont été les plus féroces. Ce qui en fait un golem aux origines lacunaires et très rare dans la nature, à l''instar des golems issus des magies primordiales. Il existe cependant une légende à son sujet : la déesse Mirada aurait invoqué ces juges arcaniques pour mettre un terme aux folles exactions des mages aux desseins chaotiques. Rien cependant n''explique leur présence continue sur les lieux où leur "jugement" à pris effet. Malheureusement, les golems n''ouvrent presque jamais la bouche, si bien tenté qu''il en ait une.

La rencontre avec ces fantômes divins peut s''avérer extrêmement dangereuse lorsque l''heure de l''affrontement a sonné. En effet, les Golems d''Arcane disposent d’armes naturelles capables de frapper l’armure magique et non physique, en plus d’être totalement fantomatiques donc immunisés contre les armes non magiques. Il est même possible pour certains des plus grands spécimens de renvoyer une partie de vos propres sorts. Si vous réussissez l''exploit de les vaincre, vous pourrez parfois constater qu''une rune s''est dessinée à l''endroit où leur ils ont succombés, en plus de libérer le Crachin Blanc sur les lieux de sa mort et cela pendant des jours. Bien que l''effet de cette rune est connu, sa forme varie selon l''individu et a une signification jusqu''ici inconnue…

Comme pour le golem de rouage et de chair, non seulement il est interdit de construire de tel golem mais en plus la façon de les faire a disparu.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 11319-11566', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-dargile', 'Golem d’argile', 'golem-dargile', 56, 'G', 'EP1', 1, 1, 'Les golems d''argiles sont les premiers golems créés par les Maverickiens. Bien qu''on puisse en trouver naturellement dans les lacs d''argiles, rien n''empêche que ce golem a servi et sert toujours de base pour tous les golems artificiels. Son corps malléable rend sa création facile, il suffit d''une bonne quantité d''argile, un peu d''huile de coude et un longue incantation pour lui donner vie. Bien sûr, seuls les utilisateurs de la magie de la Terre savent y faire.

À part ça, ce sont des golems résistants à beaucoup de magies.', 'Ici et là, Plaine, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 11573-11812', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-bois', 'Golem de bois', 'golem-de-bois', 57, 'G', 'EP1', 1, 1, 'Le golem de bois est une créature façonnée à partir de troncs anciens et de branches vivantes ou alors qui apparaît naturellement comme la réponse d’une forêt en colère. Son torse massif porte un unique œil sculpté dans l’écorce, qui semble scruter quiconque ose pénétrer la forêt. Chaque pas qu’il fait résonne comme la chute d’un arbre. D’une lenteur implacable, il avance pour repousser toute menace.

Protecteur des bois, il incarne la patience des forêts. Sa seule présence suffit à rappeler que la nature est souvent rancunière.', 'Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 11819-12069', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-boue', 'Golem de boue', 'golem-de-boue', 58, 'G', 'EP2', 2, 2, 'Le golem de boue est une créature imposante, formée d’un mélange mouvant de terre détrempée et d’argile sombre. Son corps large et bosselé paraît sculpté dans un marais vivant, parcouru de fissures d’où s’échappe un limon gluant. Sa tête informe n’a souvent qu’une simple fente luisante en guise de regard, comme un œil unique suintant de vase. De ses bras massifs émergent de longues griffes tranchantes. Le golem de boue est le gardien silencieux des marécages et des rivières polluées, surgissant des eaux troubles pour défendre son territoire.

Sa forme instable le rend presque impossible à blesser durablement, car il reconstitue sans cesse sa masse avec la terre environnante.', 'Marais, Égoût, Rivière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 12075-12343', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-chair', 'Golem de chair', 'golem-de-chair', 59, 'G', 'EP9', 9, 9, 'Véritables abominations de chair, plusieurs corps morts recollés ensemble pour former un être difforme et sans âme. Ce golem est considéré comme une véritable hérésie au sein de la religion du Sang car c''est une profonde insulte envers la chair et la vie. Les adeptes du Sang qui produise ces monstres sont poursuivis pour finalement subir et périr des suites d''une sorte de torture très cruelle qui n''est connue que par les Prêtres du Sang.
Ce golem ne paie pas de mine par son apparence distordue mais la comble par sa potentielle force physique. Qui dit muscle dit forcément puissance à ne pas sous-estimer. Il possède aussi la capacité de modifier complètement son corps pour s''adapter à son environnement ou bien simplement de manière purement aléatoire, ce qui rappelle fortement les sorts de "Sang" et le sort "Taille disproportionné" de la magie du Sang.

Vaincre cette créature est une véritable épreuve.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 12349-12646', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-corail', 'Golem de corail', 'golem-de-corail', 60, 'G', 'EP5', 5, 5, 'Le golem de corail est une entité unique née des profondeurs marines, une conscience collective de coraux qui a fusionné pour donner naissance à une forme humanoïde. Son corps est un entrelacs de branches calcaires et d’éponges colorées, rappelant un squelette vivant aussi fragile qu’implacable. Contrairement à d’autres golems, il est impossible d’en fabriquer artificiellement, seuls les récifs anciens et mystérieux peuvent en engendrer un. Bien qu’il bouge lentement, il reste puissant une fois qu’il arrive devant sa cible.

Sa particularité la plus inquiétante est sa capacité à parasiter les corps noyés ou morts qu’il rencontre, les recouvrant de coraux jusqu’à les transformer en Squelrail, des squelettes entièrement colonisés par le corail, obéissant à sa volonté. Gardien des fonds marins, il veille sur les récifs et punit ceux qui cherchent à piller la mer, incarnant à la fois la beauté et la cruauté de l’océan.', 'Mer, Plage, Rivière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 12652-12926', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-corail-2', 'Golem de corail', 'golem-de-corail', 61, 'G', 'EP5', 5, 5, 'Le golem de corail est une entité unique née des profondeurs marines, une conscience collective de coraux qui a fusionné pour donner naissance à une forme humanoïde. Son corps est un entrelacs de branches calcaires et d’éponges colorées, rappelant un squelette vivant aussi fragile qu’implacable. Contrairement à d’autres golems, il est impossible d’en fabriquer artificiellement, seuls les récifs anciens et mystérieux peuvent en engendrer un. Bien qu’il bouge lentement, il reste puissant une fois qu’il arrive devant sa cible. Sa particularité la plus inquiétante est sa capacité à parasiter les corps noyés ou morts qu’il rencontre, les recouvrant de coraux jusqu’à les transformer en Squelrail, des squelettes entièrement colonisés par le corail, obéissant à sa volonté. Gardien des fonds marins, il veille sur les récifs et punit ceux qui cherchent à piller la mer, incarnant à la fois la beauté et la cruauté de l’océan.', 'Mer, Plage, Rivière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 12934-13205', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-cristal', 'Golem de cristal', 'golem-de-cristal', 62, 'G', 'EP4', 4, 4, 'Surnommé aussi le “Chasseur invisible”, il s''agit d''un golem particulièrement dangereux. En effet, il possède la capacité unique de se rendre invisible à l''œil nu mais aussi capable d’ignorer toutes défenses.. Ce chasseur défiant par sa présence les lois de l''univers, n''existe que pour traquer les êtres qui détiennent un savoir interdit. Il est rare de croiser ces êtres, encore plus d''en être victime, mais beaucoup de parents utilisent ce qu''ils croient être une légende pour effrayer leurs enfants turbulents. Les voleurs et assassins admirent cette créature et sa discrétion légendaire.
Ils sont quasiment inexistants à l’état naturel et il est difficile de les fabriquer, le savoir pour les fabriquer est perdu depuis longtemps. Ils sont considérés comme des agents de Mora, venus pour tuer ceux qui auraient mis la main sur un savoir interdit.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 13212-13487', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-fer', 'Golem de fer', 'golem-de-fer', 64, 'G', 'EP2', 2, 2, 'Géant entière de fer à l''apparence d''un humanoïde dans une armure fait pour le combat, ils sont toujours fabriqué sous des réglementation assez strictes, la plupart des golems de fer ne dépassent pas la taille des 2m50 car leur pouvoir de destruction est telle qu''il pourrait rasé des villes entière s''ils sont trop massif.', 'Grotte, Lac de fer, Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 13766-14018', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-foudre', 'Golem de foudre', 'golem-de-foudre', 65, 'G', 'EP5', 5, 5, 'Version évolué des golem de mine, les golem de foudre sont des créatures très sophistiqué qui est en grosse majorité d’origine artificielle. On peut en retrouver à l’état naturel mais ils sont assez facilement identifiable par leur apparence comme beaucoup plus brut et moins sophistiqué que les artificiels. Ils sont parfaitement adaptés au travail dans les mines et sont même idéal pour trouver des filons de métaux. Leur corps complètement fait de métal de différent type rendent son corps dur et capable d’attirer la foudre pour la redistribuer dans une autre direction.', 'Mine, Caverne', NULL, 'monstres', 'Bestiaire 2.0 › lignes 14024-14286', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-glace', 'Golem de glace', 'golem-de-glace', 63, 'G', 'EP4', 4, 4, 'Le golem de glace est une imposante statue vivante, façonnée dans la plus pure des glaces, aux formes humaines parfaitement sculptées. Dépourvu de visage, il incarne l’absence d’âme et de compassion, avançant implacablement dans le blizzard éternel d’Enhor, son unique domaine. On ne le trouve que dans ces terres glacées, là où tempêtes et sommets enneigés forgent son essence. Contrairement à d’autres golems, il ne dispose d’aucune défense physique : ses membres de glace se brisent facilement. Pourtant, son corps est protégé par une défense magique colossale qui le rend difficile à gérer sur le plan magique. Chaque coup reçu se dissipe comme s’il frappait le blizzard lui-même, tandis que le golem continue d’avancer, froid et inébranlable, symbole éternel de la glace.', 'Enhor, zone de froid extérieur ou intérieur', NULL, 'monstres', 'Bestiaire 2.0 › lignes 13495-13760', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-lumiere', 'Golem de lumière', 'golem-de-lumiere', 70, 'G', 'EP3', 3, 3, 'Le golem de lumière est une sentinelle élancée, forgée dans un matériau qui semble rayonner de l’intérieur. Plus petit et plus agile que les autres golems, il adopte toujours une silhouette féminine, en hommage à la déesse de la lumière. Il manie un arc façonné dans une matière translucide, capable de créer des flèches de lumière pure. Ces projectiles percent ses adversaires et peuvent aveugler leurs cibles à l’impact. Souvent posté sur les hauteurs ou aux abords des sanctuaires, il veille et frappe avec précision toute menace approchant.

Là où les autres golems écrasent par la force, celui-ci terrasse à distance.', 'Là où la lumière pointe le plus fort', NULL, 'monstres', 'Bestiaire 2.0 › lignes 15329-15585', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-magma', 'Golem de magma', 'golem-de-magma', 67, 'G', 'EP4', 4, 4, 'Le golem de magma est une créature née du feu et de la roche. Son corps est formé d’obsidienne noire parcourue de veines incandescentes, laissant échapper en permanence de la lave en fusion. On le rencontre dans les volcans ou dans les terres embrasées, où il erre à la recherche de nouvelles pierres à fusionner à son corps. Leurs bras, façonnés comme d’énormes canons, peuvent projeter des blocs de magma explosif capables de réduire en cendres murs, fortifications et champs entiers. C’est cette capacité qui a fait d’eux des armes vivantes redoutées, souvent exploitées comme machines de guerre par ceux qui parviennent à les contrôler.

Lents mais puissants, les golems de magma incarnent la colère du feu, celui qui détruit tout sur son passage.', 'Volcan, Terres brûlés, Montagne', NULL, 'monstres', 'Bestiaire 2.0 › lignes 14588-14858', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-marbre', 'Golem de marbre', 'golem-de-marbre', 66, 'G', 'EP7', 7, 7, 'Les Golems de marbre sont des créatures érigées par de grands sculpteurs également doués en magie de la Terre. Généralement de manufacture elfique, ces golems réalisent le vœux de nombreux artistes : donner vie à son œuvre au sens littéral du terme. Gargouilles, statues de dieux et déesses, de héros et héroïnes, ... l''Imagination et la motivation du sculpteur seront les uniques limites en ce qui concerne la forme, la taille et la puissance du golem. Malgré toute la malévolence et la folie de ces sculpteurs, leur œuvre représente toujours une figure faisant partie du Bien et de la Loi. Mais il semblerait que l''âme de ces idoles ait influencé ces gardiens du passé. Si bien même que lorsque les Golems de Vitrail et de Marbre se croisent, il ne peut y avoir que duel à mort, imitant leurs aînés qui jadis combattaient pour leurs convictions.

D''autre part, le Golem de Marbre est un monstre de Force mais disposant de beaucoup de résistances. Cependant, le golem est bien trop rigide pour bouger, c''est pour cela que ses créateurs ont inclus dans ses articulations principales de la glaise malléable pour les laisser libres de leur mouvement. Il est donc très important de viser ces points morts si on souhaite vaincre cette idole.

Même si les hommes se pardonnent, les ombres du passé ne le permettent pas.', 'Temple, Lieu de culte, Cathédrale', NULL, 'monstres', 'Bestiaire 2.0 › lignes 14292-14578', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-maverium', 'Golem de maverium', 'golem-de-maverium', 68, 'G', 'EP10', 10, 10, 'Le golem de Maverium est une création artificielle d’une puissance inégalée, forgée entièrement dans le plus solide des alliages de Maverick, en l’an 195. Haut de 3m50, il incarne la perfection mécanique de ce qui a été une collaboration entre les forgerons nains et elfes dorés. Les premiers modèles furent déployés durant le Cataclysme Brillant, la guerre fratricide qui opposa les elfes dorés à leurs anciens esclaves, les elfes argentés. D’une stature colossale, son corps massif est fait de plaques de Maverium poli, brillant d’un éclat métallique qui ne ternit jamais.

Sa force brute lui permet d’écraser murs et armées, mais son véritable atout est sa résistance unique : il est totalement imperméable à la magie. Aucun sort, aucune malédiction, aucune invocation ne peut l’atteindre. Ainsi, il fut conçu pour briser la suprématie magique des elfes argentés. Même les siècles n’ont aucune emprise sur lui : les golems de Maverium ne rouillent pas, ne se fissurent pas et restent éternellement prêts à la guerre.

Seulement 20 en ont été construits, 10 par les elfes dorés, 5 par les humains et 5 par les nains. Il est difficile de dire combien il en reste encore dans la nature et surtout .. combien d’entre eux sont encore actifs … La création d''un tel Golem est totalement interdite et est passible de peine de mort, car ces golems sont non seulement très difficile à détruire mais en plus sont assez puissant pour raser des villes entières.

Symbole d’arrogance et de puissance, ils sont aujourd’hui presque éteints, mais leur simple évocation suffit à raviver la mémoire du Cataclysme Brillant.', '???', NULL, 'monstres', 'Bestiaire 2.0 › lignes 14864-15013', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-nuage', 'Golem de nuage', 'golem-de-nuage', 69, 'G', 'EP8', 8, 8, 'Les golems de nuages sont des colosses dont la méthode de fabrication a été perdue par son créateur car il n''a laissé aucune note. Ces êtres éthérés d''environ 4 mètres sont faits d''un squelette métallique qui est capable d''attirer les nuages pour en faire une protection plutôt unique. Leur corps a une forme humanoïde, possédant des bras et des jambes et des filaments de nuage faisant penser à des cheveux longs épais.
Ces colosses sont de très bons combattants capables de flotter dans les airs quand ils ont suffisamment de matière, ils sont très sensibles à la météo et sont capables d''être totalement différents selon la météo en cours.', 'Île céleste', NULL, 'monstres', 'Bestiaire 2.0 › lignes 15019-15323', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-pain', 'Golem de pain', 'golem-de-pain', 72, 'G', 'EP3', 3, 3, 'Le golem de pain est une créature humanoïde aussi insolite que redoutable, façonnée à partir de miches et de pâte cuite. Du haut de ses 2m en moyenne, sa surface dorée craque légèrement à chaque mouvement, laissant échapper une odeur appétissante qui trompe souvent les imprudents. Ces golems, rares par nature, sont le plus souvent rencontrés dans les cuisines ou les boulangeries, créés artificiellement pour protéger des réserves précieuses ou surveiller des champs de blé. Les spécimens artificiels présentent des formes nettes, travaillées avec soin, parfois décorées. Les golems naturels, eux, naissent sans aucunes explications au cœur des champs de blé, et bien que plus grossiers dans leur apparence, ils entretiennent les récoltes avec un soin tout aussi inexpliqué.

Qu’ils soient façonnés par la main d’un maître boulanger ou apparus de façon spontanée, tous partagent une mission commune : défendre farouchement le blé.', 'Les champs de blé, Boulangerie', NULL, 'monstres', 'Bestiaire 2.0 › lignes 15856-16143', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-pain-dor', 'Golem de pain d’or', 'golem-de-pain-dor', 73, 'G', 'EP5', 5, 5, 'Le Golem de Pain Doré, du haut de ses 3 mètres, est une variante rare et exclusivement naturelle du golem de pain, née au cœur de la Plaine Brillante, là où pousse le légendaire blé d’or. Plus imposant et plus harmonieux dans ses proportions, il possède une croûte brillante aux reflets presque métalliques, comme si chaque parcelle de sa surface captait la lumière du soleil. Des boulangers ont tenté de reconstruire un tel golem mais ça n’a jamais fonctionné, il est admis aujourd’hui que ce golem ne peut pas être fabriqué artificiellement.
Contrairement aux golems façonnés par des mains humanoïdes, le Golem de Pain Doré apparaît spontanément parmi les champs dorés. Il ne se contente pas de défendre les récoltes : il semble en être une émanation vivante, un gardien naturel du blé d’or. Sa présence favorise parfois la croissance des cultures, et les épis alentours semblent plus vigoureux sous sa vigilance silencieuse.
Sa particularité réside dans sa croûte réactive à la magie. Lorsqu’il est frappé ou exposé à un élément, sa surface change de propriété : face au feu, elle se durcit et devient presque incandescente ; sous l’effet de l’eau, elle gagne en souplesse et en élasticité ; confrontée au vent ou à la foudre, elle peut devenir plus légère ou conductrice. Cette adaptation élémentaire le rend imprévisible et particulièrement difficile à neutraliser. Défier un Golem de Pain Doré revient à affronter une force qui s’adapte et se renforce à chaque tentative de l’abattre.', 'Plaine brillante', NULL, 'monstres', 'Bestiaire 2.0 › lignes 16151-16512', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-petrole', 'Golem de pétrole', 'golem-de-petrole', 74, 'G', 'EP6', 6, 6, 'Le golem de pétrole est une créature aux origines mystérieuses. Selon des rumeurs, leur création proviendrait d''un mélange entre du brai et de la corruption. Mais certains affirment que le brai utilisé pour créer ces abominables golems n''est pas de la colle traditionnelle... Certains affirment que quelque chose de vivant semble animer cette substance. Ils semblent d''ailleurs émettre depuis des puits de cette matière visqueuse où ils jaillissent lorsqu''ils sont en alerte. Ils se présentent donc sous la forme de masses difformes et utilisant leur propre agrégat de brai pour attaquer et partager la corruption autour d''eux. Il n''y a que l''eau pure et d''origine magique qui puisse venir à bout de ces abominations ou bien les lames bien aiguisées de tout type. Un des effets pervers de ces golems, c''est leur extrême inflammabilité. En effet, la moindre braise ou étincelle enflamme leur corps tout entier et les rend encore plus dangereux mais très faibles à l’eau.

Il est connu que ce golem n’existe pas en version artificiel mais qu''à l’état naturel.', 'Marais', NULL, 'monstres', 'Bestiaire 2.0 › lignes 16518-16851', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-rouage', 'Golem de rouage', 'golem-de-rouage', 75, 'G', 'EP9', 9, 9, 'Le golem de Rouage est un gardien mécanique énigmatique, dont le corps est constitué d’innombrables engrenages de cuivre qui tournent sans jamais s’arrêter. Des lueurs rosées brillent dans ses zones sensibles, comme son cœur et sa tête, rappelant une énergie d’origine divine. Selon les légendes, ces colosses auraient été bénis par les dieux du Temps et de l’Espace afin de protéger les mystères les plus dangereux de ces magies. Leur mission sacrée est de traquer et punir ceux qui osent manipuler l’espace-temps de façon abusive. Bien que rares, on les aperçoit parfois au détour d’une faille dimensionnelle, surgissant comme des ombres mécaniques hors de la réalité. Comme tous les golems, ils ne font preuve d’aucune hésitation : toute intrusion dans leur domaine est perçue comme une menace, et ils attaquent avec une précision implacable.

Leurs rouages résonnent alors comme le tic-tac d’une horloge fatale, annonçant la fin pour ceux qui se dressent contre eux.
Comme pour le golem d’arcane et de chair, non seulement il est interdit de construire de tel golem mais en plus la façon de les faire a disparu.', 'Faille temporelle, Couloir du temps', NULL, 'monstres', 'Bestiaire 2.0 › lignes 16857-17137', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-sable', 'Golem de sable', 'golem-de-sable', 76, 'G', 'EP2', 2, 2, 'On retrouve principalement cette créature dans les confins du désert doré. Là où les dunes se concentrent en petit comité et où les tempêtes font rage. Ce golem particulier est comme une sorte de squelette fait en sable durcie dans lequel toutes les zones de vide sont comblées par du sable qui bouge en permanence, comme des sables mouvants.

Cette disposition fait que cette créature est assez difficile à tuer dans son environnement vu qu’elle y tire sa puissance, voire même son existence.', 'Désert', NULL, 'monstres', 'Bestiaire 2.0 › lignes 17144-17409', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-sel', 'Golem de sel', 'golem-de-sel', 77, 'G', 'EP3', 3, 3, 'Le Golem de Sel est une créature élémentaire instable, façonnée à partir de blocs de sel grossier compactés par la magie primitive de la Terre et de l’Eau. Son apparence anguleuse, presque cristalline, donne l’impression d’une statue mal dégrossie, dont chaque mouvement fait grincer et craquer la surface en un bruit sec caractéristique.
Variant grandement en taille, les plus petits mesurent environ 1,60 mètre, tandis que les plus imposants peuvent culminer à 3,5 mètres, véritables colosses translucides aux reflets nacrés. Leurs yeux ne sont que deux cavités luminescentes où scintille une énergie aqueuse contenue sous pression.
Malgré leur allure massive, les Golems de Sel sont d’excellents nageurs. Leur structure, imbibée en profondeur d’eau, leur confère une flottabilité et une souplesse surprenante. Dans l’eau, ils deviennent fluides, se déplaçant avec une aisance qui contredit totalement leur silhouette rigide lorsqu’ils marchent sur terre.
Sur la terre ferme, c’est l’inverse : ils avancent avec une puissance brute, chaque pas faisant vibrer le sol. Dans leurs coups, on ressent la masse compacte de leur corps entier, capable de briser de la pierre.', 'Plage, Mer', NULL, 'monstres', 'Bestiaire 2.0 › lignes 17417-17699', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-verre', 'Golem de verre', 'golem-de-verre', 78, 'G', 'EP5', 5, 5, 'Les Golems de Verre sont des créatures que l''on retrouve principalement dans les déserts et verreries. Les rares spécimens trouvés à l''état naturel sont d''anciens golems de sable ayant subi une forte pression suite à une explosion de grande ampleur. Ce qui rend leur origine souvent difficile à expliquer, même si certains ont été créés accidentellement suite à des combats impliquant un puissant utilisateur du Feu. Pour ce qui est des spécimens artificiels, ils sont tout simplement créés par des maître-verriers, avec autant de raffinement et de précision que les sculpteurs de golems de marbre.', 'Désert, Verreries', NULL, 'monstres', 'Bestiaire 2.0 › lignes 17705-18004', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-de-vitrail', 'Golem de vitrail', 'golem-de-vitrail', 79, 'G', 'EP7', 7, 7, 'Le Golem de Vitrail est une créature purement artificielle. Issue des mêmes techniques de fabrications que le Golem de Verre. Le verre préalablement coloré est chauffé à très haute température et maintenu par des baguettes de plomb afin de former des motifs, répétitifs, pour représenter un personnage important tels qu''une divinité ou un héros. Dans le cas de ces golems, ce sont plutôt des personnages oubliés, des démons aux concepts maléfiques et chaotiques qui forment l''apparence isométrique de ces derniers. Mais il semblerait que l''âme de ces idoles ait influencé ces gardiens du passé. Si bien même que lorsque les Golems de Marbre et de Vitrail se croisent, il ne peut y avoir que duel à mort, imitant leurs aînés qui jadis combattaient pour leurs convictions.

D''autre part, le Golem de Vitrail est un monstre d''agilité mais aussi très résistant aux affres du temps à votre lame. Cependant, le golem surchauffe très vite et a besoin d''exposer son cœur pour ne pas fondre bêtement. Comme nous, son cœur est son seul et unique point faible qu''il ne faut pas négliger si on souhaite vaincre cette idole. Son cœur semble d''ailleurs battre comme un cœur organique.

Même si les hommes se pardonnent, les ombres du passé ne le permettent pas.', 'Désert, Verreries, Temple, Cathédrale', NULL, 'monstres', 'Bestiaire 2.0 › lignes 18010-18350', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-dombre', 'Golem d’ombre', 'golem-dombre', 71, 'G', 'EP3', 3, 3, 'Le golem de l’ombre est une silhouette élancée et élégante, sculptée dans une matière sombre qui absorbe la lumière autour de lui. Toujours raffiné, il porte l’apparence d’un noble ou d’un assassin masqué, rappelant le style sophistiqué du dieu de l’ombre. Ses mouvements sont silencieux, presque irréels, et ses contours semblent se fondre dans les ténèbres à chaque pas. Il manie deux lames formées d’ombre pure, qui se reforment instantanément lorsqu’elles sont brisées ou dissipées.

Gardien discret des lieux secrets ou protecteur des passages oubliés, il préfère éliminer ses ennemis avant même qu’ils ne réalisent qu’il est là.', 'Là où l’ombre domine', NULL, 'monstres', 'Bestiaire 2.0 › lignes 15593-15848', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/golem-osseux', 'Golem osseux', 'golem-osseux', 80, 'G', 'EP6', 6, 6, 'Le golem osseux est un amalgame de squelettes, portant avec eux toute la noirceur de leurs âmes dérangées de leur repos éternel. Les corps sont broyés pour constituer le corps de ce géant poussiéreux et sinistre, imitant l''anatomie d''un ogre ainsi que leur cruauté envers leurs collègues qu''ils fustigent de leur fouet squelettique. Même si ce golem est normalement, uniquement artificiel, certains affirment que lors de certaines nuits, les cimetières et ossuaires abandonnés ainsi que champs de batailles oubliés se réveillent à l''occasion. C''est alors que ces gardiens surgissent et poussent un cri de douleur terrifiant, comme pour faire comprendre aux vivants que les morts les observent toujours.', 'Ruines, Champ de bataille, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 18360-18642', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/griffon', 'Griffon', 'griffon', 81, 'G', 'EP4', 4, 4, 'Dans la longue liste des mille et un dangers qui attendent les fous et les braves, les griffons occupent une place de choix. Créatures mi-félin mi-aigle, quadrupèdes au pelage brun/or et dotées de griffes d’acier, ils règnent sur les massifs montagneux et les hauts plateaux venteux. Farouches défenseurs de leur territoire et de leurs engeances, ils attaquent sans hésiter quiconque s’approche trop près de leurs nids ou de leur groupe, surtout lorsqu’un intrus est pris pour un envahisseur — une erreur fréquente chez les ignorants.
Malgré leur réputation redoutable, les griffons sont aussi des symboles de fierté et de bravoure, abondamment représentés dans les peintures, sculptures et tapisseries de nombreuses cultures. Leur hostilité n’est jamais gratuite : ils ne font que protéger ce qui leur appartient. Envers les Maverickiens, leur comportement est souvent plus mesuré, et il arrive même que de jeunes griffons acceptent l’apprivoisement. On en retrouve ainsi dans certaines armées humaines, les griffons se montrant étonnamment plus réceptifs à la présence des humains qu’à celle d’autres peuples.
Liés à la magie du Vent et de la Foudre, les griffons les plus féroces en sont totalement immunisés. Leurs cris peuvent se mêler au tonnerre et leurs battements d’ailes fendre l’air. Passés maîtres dans l’art de la riposte, ils disposent de réflexes inégalables : toute agression mal calculée se solde presque toujours par une riposte fulgurante. Affronter un griffon, c’est défier à la fois la bête et le ciel…
Taille adulte
Hauteur garrot : 2 mètres maximum
Longueur : 3,5 mètres
Envergure : 7 - 10 mètres', 'Montagne, Colline', NULL, 'monstres', 'Bestiaire 2.0 › lignes 18648-18845', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/hallebarde-amochee', 'Hallebarde amochée', 'hallebarde-amochee', 82, 'H', 'EP2', 2, 2, 'La Hallebarde Amochée est une silhouette spectrale saisissante : une longue hallebarde tordue, au fer ébréché et piqué de rouille, flottant comme tenue par des mains invisibles. Le spectre qui l’anime, d’un vert sombre profond, semble plus étiré et plus grand que celui des autres membres du cortège, comme si son arme déformait jusqu’à son aura. Ses mouvements sont lents lorsqu’il patrouille, mais deviennent brusques et terriblement précis lorsque la menace se présente.
Membre du Cortège du Passé, la Hallebarde Amochée partage le même rôle que l’Épée Rouillée : celui d’un frappeur offensif, conçu pour briser les intrus sans hésitation. Mais là où l’épée charge au corps-à-corps pour découper tout ce qui s’approche, la hallebarde agit comme un bras armé à distance, capable d’atteindre ses ennemis avant même qu’ils n’arrivent à portée. Lorsque les deux spectres combattent côte à côte, ils forment un duo meurtrier : l’Épée Rouillée harcèle de près tandis que la Hallebarde Amonchée couvre les lignes, empêchant tout repli.
En combat, ses attaques sont amples, puissantes et implacables. Elle balaye, transperce ou repousse les intrus sans jamais émettre un son, seul le bruit du fer qui tranche la chair et le sang qui coule brise ce silence. Quiconque voit sa silhouette en retrait sait que l’offensive du cortège ne fait que commencer… et que reculer ne suffira pas à survivre.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 18848-18908', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/herbe-folle', 'Herbe folle', 'herbe-folle', 83, 'H', 'EP2', 2, 2, 'Les Herbes Folles sont des créatures végétales nées d’expériences alchimiques ayant mal tourné. Initialement cultivées pour servir de catalyseurs dans des potions, elles ont fini par s’adapter à la vie sauvage, formant des colonies dans des zones riches en blobs, dont elles se nourrissent avidement. Les plus petites font 40cm de haut, les moyennes 80cm et les plus grosses 1m60.

Ces plantes sont particulièrement prisées par les herbivores, car elles dégagent une saveur et odeur raffinée et contiennent des essences utilisées en cuisine et en alchimie. Leur corps sphérique est parsemé de trous sombres, et leur croissance est influencée par leur alimentation. Leurs feuilles changent de couleur en fonction des nutriments qu’elles absorbent, du blob qu’elles rafollent et de leur environnement, les feuilles sont un indice de quelle magie elles sont, il suffit d’observer la couleur.

Lorsqu’elles se sentent en danger, les Herbes Folles possèdent une capacité unique : la fusion. Elles combinent leurs corps et leurs consciences, formant une créature plus grande et plus robuste. Le nombre d''yeux visibles sur leur corps témoigne du nombre d’individus ayant fusionné, un trait hérité de leur nature inspirée des blobs.

Bien qu’elles ne soient ni des prédateurs agressifs ni des créatures puissantes, leur nature semi-intelligente leur permet d’élaborer des stratégies pour échapper aux menaces ou piéger leurs proies.', 'Forêt, Plaine, Lac, Plateau', NULL, 'monstres', 'Bestiaire 2.0 › lignes 18913-19081', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/irapullum', 'Irapullum', 'irapullum', 84, 'I', 'EP3', 3, 3, 'Variante monstrueuse de l’Équipullum, cette créature est le fruit d’une corruption mêlant magie du Sang et de la Terre. Son corps, agrandi de façon anormale, présente des muscles plus développés, une peau fissurée par des excroissances minérales, et des griffes épaisses capables de trancher la roche. Ses mâchoires, déformées par l''évolution de son régime cannibale, sont désormais adaptées à broyer la chair et les os.', 'Plaines, Forêts, Anciens champs de bataille', NULL, 'monstres', 'Bestiaire 2.0 › lignes 19084-19261', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/jambieres-moisies', 'Jambières moisies', 'jambieres-moisies', 85, 'J', 'EP2', 2, 2, 'Les Jambières Moisies sont un spectre d’apparence inquiétante : deux jambières anciennes, fendues et rongées par la corrosion, flottant dans l’air comme si un corps invisible se tenait à l’intérieur. Le fantôme qui les anime est un voile d’un vert sombre, plus étroit et nerveux que celui des autres membres du cortège, n''apparaît de sa forme cauchemardesque que quand il attaque ou esquive. Ses contours vibrent légèrement, comme une ombre impatiente prête à bondir, et chaque mouvement laisse une traînée éthérée presque imperceptible.
Au sein du Cortège du Passé, ces jambières hantées représentent l’ombre meurtrière, l’assassin silencieux qui avance loin du groupe. Là où la Cuirasse Abîmée bloque, où l’Épée Rouillée charge et où le Casque brisé affaiblit, les Jambières Moisies se glissent hors du regard, contournent, observent et attendent le moment idéal pour frapper. Leur spectre semble avoir conservé les réflexes d’un tueur autrefois vif et précis.
En combat, elles apparaissent dans le dos ou le flanc de leurs cibles avec une rapidité déroutante. Leur attaque est une estafilade spectrale, un coup furtif qui vise les points faibles. Une fois leur frappe portée, elles disparaissent aussitôt dans une volute sombre pour réapparaître quelques mètres plus loin, prêtes à recommencer. Leur présence, presque impossible à anticiper, fait des Jambières Moisies l’un des membres les plus redoutés du cortège… et souvent le dernier aperçu avant de sombrer dans l’obscurité.', 'Ruines, Cimetière', NULL, 'monstres', 'Bestiaire 2.0 › lignes 19268-19326', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/karn', 'Karn', 'karn', 86, 'K', 'EP2', 2, 2, 'Le Karn est un quadrupède massif au corps trapu et compact, culminant à environ 1,30 mètre au garrot. Son crâne large est encadré par deux paires de cornes spiralées, épaisses et robustes, capables de briser bois et os lors d’une charge. Sa laine, dense sans être excessivement touffue, possède une particularité remarquable : elle adapte naturellement sa teinte à la magie dominante de la région où il évolue. Le brun terreux reste la coloration la plus répandue, reflet de son affinité naturelle avec la Terre.
Présent dans pratiquement tous les biomes — plaines, montagnes, marais, déserts — le Karn adapte subtilement sa physiologie à son environnement. Son régime est omnivore opportuniste : il broute herbes et racines mais ne rechigne pas à mâcher cuir, bois, métal ou même chair. Ses mâchoires puissantes peuvent broyer équipement et armure, ce qui le rend redoutable à l’état sauvage. Craintif de nature, il vit en hardes de 5 à 20 individus et celui que l’on nomme le chef de guerre n''hésite pas à aller en première ligne pour défendre son groupe, il se reconnaît facilement, c’est celui qui a le plus de blessures et le plus gros. Il n’est jamais une bonne idée de s’en prendre à un petit, les adultes n''hésiteront pas à attaquer tous ensemble.
Malgré son côté sauvage, le Karn a pu être domestiqué et est devenu une bête de somme qui se retrouve de partout dans le monde. Une fois apprivoisé, il peut même devenir une monture solide et endurante. C’est un animal précieux : laine, lait, viande, cuir et cornes sont exploités par de nombreuses cultures. Le mâle est appelé Karn, la femelle Karne, et le petit Karnet. Bien que ses variations soient nombreuses selon l’élément dominant de son habitat, les Karns liés à la Terre restent les plus communs et les plus emblématiques de l’espèce.
D’une manière générale on distingue deux type de karn :
* Le karn apprivoisé qui est exploité pour ses nombreuses ressources plus qu’utile et sa force de travail.
* Le karn sauvage qui continue a peuplé le monde et qui est parfois chassé par des prédateurs ou des chasseurs.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 19331-19593', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/loup-garou', 'Loup-garou', 'loup-garou', 87, 'L', 'EP1 - 10', 1, 10, 'Le Loup-Garou est un démon, une abomination née d’une exposition prolongée au nuage de Kcirevam. Jadis un Fenrir, cette créature a été déformée, corrompue jusqu’à perdre toute raison. Sa musculature a doublé, sa fourrure s’est épaissie, et sa taille dépasse désormais celle des plus grands fenrirs. Sa tête, autrefois humanoïde, est devenue celle d’un loup monstrueux — symbole de la sauvagerie totale qui l’habite désormais.
En plus d’avoir une force brute, il incarne l’instinct de prédation à l’état pur. Possède les trois magies liées aux fenrirs, il les exploite à leur plein potentiel et à son avantage, il utilisera tous les outils à sa disposition pour détruire ses ennemis.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 19599-20030', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/lumiphage', 'Lumiphage', 'lumiphage', 88, 'L', 'EP7', 7, 7, 'Un squelette émanant d''une lumière aveuglante que l''on retrouve dans les anciens sites de culte de la Lumière. Selon les rumeurs, se seraient d''anciens défenseurs de la Lumière parjures, suite à un dévouement trop prononcé pour Aurora. Ils auraient conclu un pacte mystérieux qui leur permet d''honorer malgré la mort et le manquement aux lois, de pourfendre le mal et de convertir les infidèles à la bonté de la Vierge Solaire.
Il ne sert pas les vivants : il sert la lumière elle-même, de manière aveugle et implacable, sans compassion ni nuance.', 'Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 20034-20221', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/luperoc', 'Lupéroc', 'luperoc', 89, 'L', 'EP3', 3, 3, 'Le Lupéroc est un loup sauvage profondément lié à la magie de la terre. Son corps massif est renforcé par des plaques de roche naturelles qui se mêlent à sa fourrure sombre, formant une véritable armure minérale. Ces excroissances de pierre varient d’un individu à l’autre : les plus jeunes n’en possèdent que quelques-unes sur le dos, tandis que les anciens, plus puissants, sont presque entièrement enchâssés dans la roche. Il se déplace avec une étonnante souplesse malgré son apparence lourde. Ses pattes, parfois presque entièrement recouvertes de pierre, lui permettent de fouler les sols rocailleux sans bruit, comme si la terre elle-même assourdissait ses pas.
Les Lupérocs sont des animaux sociaux, vivant en meutes hiérarchisées où la force physique et le lien de la magie déterminent la position. Leur culture instinctive valorise l’endurance et la protection du territoire. Malgré un naturel craintif, les meutes défendent férocement leurs forêts, montagnes ou plateaux, repoussant toute menace et n’hésitant pas à attaquer ceux dont la magie est une menace (sang et feu).', 'Forêt, Montagne, Plateau', NULL, 'monstres', 'Bestiaire 2.0 › lignes 20227-20390', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/main-blanche', 'Main blanche', 'main-blanche', 90, 'M', 'EP5', 5, 5, 'Cette créature monstrueuse d''origine de Kcirevam erre dans les lieu isolés d''êtres vivants pour pouvoir mieux les attaquer. Cette créature plane dans les airs, assez massif dont les plus gros atteignent les 1m50 de haut pour 80cm de largeur, le tout pouvant peser 60Kg.

La particularité principale de cette créature est qu''elle est capable de se métamorphoser en une créature ou une personne que sa cible aime ou porte dans son cœur.
Cette créature ne possède aucune faiblesse en plus de faire beaucoup de dégâts physique comme magique.

Elles ont une particularité au combat, elles prennent une créature pour cible et ne la lâchent pas avant de l''avoir abattu. Une fois la victime au sol, elles vont planté leur veine à l''intérieur et aspirer l''énergie vitale et le sang de leur victime.', 'Désert, Verreries', NULL, 'monstres', 'Bestiaire 2.0 › lignes 20393-20444', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/masse-empoisonneuse', 'Masse empoisonneuse', 'masse-empoisonneuse', 91, 'M', 'EP6', 6, 6, 'Abomination née de l’alchimie et de la nécromancie, cette créature serpentine au corps boursouflé crache des projectiles toxiques à très longue portée. Dotée de deux bras griffus terminés par des faux osseuses, elle lacère et empoisonne tout sur son passage. Son corps suinte un poison alchimique instable, rongeant la vie et la matière.

Créée dans les ténèbres d’un laboratoire oublié, cette entité n’obéit qu’à l’instinct de destruction — et à la volonté noire de ceux qui l’ont réveillée.', 'Ruines, Laboratoire, Terre désolé', NULL, 'monstres', 'Bestiaire 2.0 › lignes 20446-20510', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/molvacier', 'Molvacier', 'molvacier', 92, 'M', 'EP3', 3, 3, 'Cette créature est une imposante taupe d’environ 90 centimètres, profondément liée aux magies de la Terre et de la Foudre. Cette combinaison élémentaire recouvre son corps d’une véritable carapace métallique, tandis que sa tête et ses griffes sont renforcées par des plaques minérales pointues. Ces protections naturelles lui permettent de creuser pendant de longues périodes à travers des sols particulièrement difficiles.
On retrouve principalement ces créatures dans les régions volcaniques et montagneuses, où elles creusent d’immenses galeries souterraines servant à délimiter leur territoire. Leur présence peut être repérée par les réseaux de tunnels qu’elles laissent derrière elles, parfois assez vastes pour former de véritables labyrinthes sous les montagnes. Elles sont capables de traverser des terrains où la plupart des autres créatures fouisseuses seraient incapables de progresser.
Lorsqu’elle est menacée, la créature utilise sa puissance tellurique pour modifier le terrain, provoquant de petits séismes, ouvrant brutalement des trous sous ses adversaires ou faisant s''effondrer certaines portions du sol. Elle peut également combattre directement avec ses griffes renforcées, dont la puissance est suffisante pour perforer de nombreuses armures. Sa carapace lui permet d''encaisser les attaques tandis que ses pouvoirs de Terre et de Foudre transforment le terrain en véritable piège pour quiconque tente de la poursuivre sous terre.', 'Volcan, Montagne, Caverne', NULL, 'monstres', 'Bestiaire 2.0 › lignes 20512-20764', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/momie', 'Momie', 'momie', 93, 'M', 'EP5', 5, 5, 'Les Momies sont des non-morts enveloppés de longues bandelettes de lin, créés pour garder les tombes des défunts importants et protéger les lieux sacrés contre toute profanation. Immobiles pendant des années, parfois des siècles, elles restent pourtant constamment à l’affût d’intrus, prêtes à se relever dès qu’une présence étrangère trouble le repos des morts. Contrairement à la majorité des non-morts, les momies ne sont pas animées par la haine de la vie : elles agissent selon un code d’honneur ancien, attaquant uniquement ceux qui osent violer les sépultures qu’elles ont juré de protéger. Aussi étonnant que cela puisse paraître, il est parfaitement possible de faire comprendre à des momies qu’il n''y a aucune volonté de pillage.
Leur création repose sur un rituel d’embaumement long et rigoureux, pratiqué selon des règles très strictes. Ce procédé est particulièrement répandu chez les adeptes de la magie de l’Espace et du Temps, qui voient dans la momification une manière de prolonger la vigilance d’un individu au-delà de la mort. Cependant, il existe une seconde méthode, plus mystérieuse : un rituel où le corps est préparé de manière à se relever un jour, sans que l’on sache exactement quand. Dans ce cas, la momie renaît lorsque le moment l’exige, comme si la volonté du temps lui-même décidait de réveiller son gardien.
Les momies gardiennes se distinguent facilement par leurs bandages teintés de rose, imprégnés d’une magie active liée à l’Espace et au Temps. Leur corps est souvent renforcé par une armure funéraire mêlant métal et bandelettes magiques, témoignage de leur rôle martial même dans la mort. Lorsqu’elles sont enterrées, elles le sont toujours avec une arbalète à une main, arme sacrée associée au dieu du Temps et à la déesse de l’Espace. Cette arme symbolique devient leur outil principal pour défendre les tombes contre les pilleurs imprudents.
Leurs bandelettes ne sont pas de simples tissus : elles sont animées par la magie, capables de se mouvoir de manière autonome. Elles peuvent manipuler des objets ou même recharger l’arbalète pour les momies plus puissantes. La momie n’a pas besoin de carquois, les carreaux sortent des bandages. Les momies sont d’excellents tireurs et combinent souvent leur adresse martiale avec leurs pouvoirs, mêlant projectiles et magie pour ralentir, piéger ou désorienter leurs ennemis.
Enfin, les momies possèdent une particularité redoutable : leur magie ne peut être réduite au silence. Aucune entrave, aucun sort, aucune capacité ne peut empêcher ces gardiens d’utiliser la magie de leurs divinités. Car aux yeux des prêtres qui les ont créées, leur vigilance ne doit jamais être brisée — ni par le temps, ni par la mort, ni par la volonté des vivants.
Le secret de ces deux rituels est gardé précieusement par une guilde liée à la nécromancie, l’espace/temps mais des rumeurs disent qu’ils sont aussi reliés à Umbro, le dieu de l’ombre. Cela pourrait expliquer la capacité de maudire.', 'Ruines, Mausolée, Souterrain, Désert', NULL, 'monstres', 'Bestiaire 2.0 › lignes 20770-21046', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/mordor', 'Mord’or', 'mordor', 94, 'M', 'EP9', 9, 9, 'Les Mord''or sont d''étranges squelettes composés en grosse majorité d''or, ils sont très résistants face aux coups physiques et possèdent de nombreuses résistances magiques. A la base ce squelette est sculpté de la même manière qu''un golem, c''est-à-dire il est construit artificiellement mais il fonctionne avec l''énergie d''une âme qu''on y a implémenté de force, ou de gré, mais c''est plus rare.
Ces formidables créatures armés d''un marteau géant erre dans les villes ou dans les ruines à la recherche d''or ou de trésor. ils ne cherchent pas le combat en premier lieu mais ils n''hésitent pas à se battre s''il y a un obstacle entre eux et le trésor convoité. Contrairement aux apparences, les Mord''or sont très discrets et use de stratégie basique pour se cacher, il est déjà arrivé d''attraper un Mord''or dans un tonneau.
Il ressemble a des squelettes humanoïde à la tête et au tronc mais les bras et les jambes sont plus géométrique et ressemble à des cylindres, ils ont que deux doigts en forme de pince mais c''est suffisant pour récupérer du trésor ou tenir leur puissante arme, leur arme est lié à leur corps et il semble impossible de la récupérer.
Surveillez bien vos richesses, même les morts veulent vous les prendre ...', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 21050-21246', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/moustique-bordeaux', 'Moustique bordeaux', 'moustique-bordeaux', 95, 'M', 'EP1', 1, 1, 'Le Moustique Bordeaux est un moustique gigantesque pouvant atteindre près d’un mètre vingt de longueur. Malgré sa taille démesurée, il ne possède rien de particulièrement exotique dans son comportement : il reste un parasite qui se nourrit exclusivement de sang. Son corps bordeaux et ses longues pattes lui permettent de se dissimuler relativement facilement dans l’obscurité, où il attend généralement qu’une proie soit immobile pour se nourrir.
Le véritable danger vient de la quantité de sang qu’il est capable d’absorber en une seule fois. Là où un moustique ordinaire ne représente qu’une nuisance, le Moustique Bordeaux peut vider une quantité considérable de sang en quelques instants. Les victimes endormies sont particulièrement vulnérables, et il arrive régulièrement qu''une personne ne se réveille jamais après avoir été prise pour cible par l''un de ces parasites.
Il faut cependant raison garder : malgré son apparence imposante, le Moustique Bordeaux reste une créature particulièrement fragile physiquement. Son affiliation au sang constitue également une faiblesse évidente, rendant certaines attaques particulièrement efficaces contre lui. Un aventurier préparé n''a donc généralement pas beaucoup de difficultés à l''abattre ; le véritable problème est de le repérer avant qu''il ne plante sa trompe dans quelqu''un.', 'Forêt, Marais, Ville', NULL, 'monstres', 'Bestiaire 2.0 › lignes 21250-21478', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/noye', 'Noyé', 'noye', 96, 'N', 'EP2', 2, 2, 'Le Noyé est un cadavre rendu à la vie par les eaux stagnantes et putrides des marécages, des égouts ou des puits oubliés. Son corps a absorbé tant d’humidité qu’il en est devenu un réservoir vivant de liquides acides, vomissant sa haine pour la vie au travers d''un liquide corrosif. Là où il passe, la chair pourrit, et le métal rouille. En plus de ses dents acérées, son vomi est capable de pénétrer les armures et de tuer à petit feu ses adversaires.', 'Ruines, Marais, Plage', NULL, 'monstres', 'Bestiaire 2.0 › lignes 21484-21655', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ogre', 'Ogre', 'ogre', 97, 'O', 'EP1 - 10', 1, 10, 'L’Ogre est un démon, une créature autrefois humanoïde, profondément altérée par une exposition prolongée au nuage de Kcirevam. Il s’agit de la forme corrompue et chaotique du Marcass, désormais métamorphosé en monstre bipolaire, aussi imprévisible que meurtrier.
Son apparence est terrifiante : sa tête est littéralement fendue en deux, comme si deux esprits cohabitaient dans un même crâne brisé, un ventre boursouflé, une musculature étrange, des crocs proéminents et des yeux brillant de la couleurs des deux magies. Cette division n’est pas qu’esthétique : chacune des moitiés possède une personnalité, un style de combat et un arsenal magique propre.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 21660-22081', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/orc', 'Orc', 'orc', 98, 'O', 'EP1-10', 1, 10, 'L''Orc est la forme démoniaque et chaotique des Elfes forestiers, une mutation qui pousse leur agilité, leurs instincts et leur adaptation à un niveau démesuré. Son corps est celui d''un prédateur né pour la forêt : maigre, sec et doté de bras comme de jambes anormalement longs qui lui permettent de grimper avec une aisance déconcertante. Sa peau pâle, marbrée de nuances grises, verdâtres ou violacées, brise naturellement sa silhouette parmi les troncs et les feuillages. Son visage est la partie la plus troublante : une tête légèrement disproportionnée, d''immenses yeux aux pupilles extrêmement dilatables qui brillent dans l''obscurité, et une calvitie centrale bordée de longues mèches qui lui donnent une apparence immédiatement reconnaissable.
L''Orc est un prédateur d''embuscade qui passe davantage de temps dans les arbres qu''au sol. Il peut demeurer parfaitement immobile pendant de longues minutes, observant le moindre mouvement avant de fondre sur sa proie avec une vitesse terrifiante. Ses réactions paraissent dépasser la réflexion elle-même : il esquive, grimpe, attaque ou change de direction avec une spontanéité presque animale, donnant l''impression que son corps agit avant même que son esprit n''ait pris une décision.
La véritable particularité de cette créature réside dans son esprit régi par la vitesse. L''Orc apprend à une vitesse prodigieuse, assimilant en quelques instants le maniement d''une arme, une technique de combat ou le fonctionnement d''un piège simplement en les observant. Cette adaptation fulgurante lui permet de retourner immédiatement les forces de ses ennemis contre eux. Mais ce don possède un revers : son esprit oublie tout aussi rapidement. Une fois le combat terminé, les connaissances acquises s''effacent progressivement, ne laissant subsister que ses instincts de chasseur. Chaque affrontement est ainsi une nouvelle leçon qu''il apprend... avant de l''oublier.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 22085-22530', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/os-du-froid', 'Os du froid', 'os-du-froid', 99, 'O', 'EP5', 5, 5, 'Un squelette qu''on retrouve dans les zones froides de Maverick, si on en croit les légendes autours de ces morts, ce serait d''anciens fidèles de la Déesse de la Glace qui aurait prêté serment au-delà de la mort via un rituel encore méconnu. Une autre théorie parle d''ancien fidèle de la Déesse de la Glace qui aurait commis une faute très grave envers cette dernière et ont été condamné à répandre l''Hiver jusqu''à la destruction de leur carcasse.
Ce sont des squelettes capables de lancer des sortilèges de la magie de la Glace et possèdent de manière permanente une armure de Glace.', 'Montagne, Neige, Forêt froide, Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 22536-22738', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-amoureux', 'Ottar Amoureux', 'ottar-amoureux', 101, 'O', 'EP1 - 10', 1, 10, 'Amalgame tragique de deux êtres dont l’amour a défié la mort : par un rituel inconnu, la chair du vivant s’est soudée à celle du disparu, ramenant une moitié à la vie au prix d’un effondrement chakratique. Ces siamois traquent implacablement les responsables de leur destin et toutes celles et ceux qui partagent leur histoire, cherchant à rayer ces noms de la mémoire collective.

Les deux moitiés sont liées : seule la ré-re-mort de la moitié d’abord décédée peut anéantir l’Ottar, mais la moitié vivante se défendra jusqu’à la folie pour l’empêcher.

Leur amour a arraché la mort, et leur vengeance arrache la mémoire.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23180-23187', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-chariot', 'Ottar Chariot', 'ottar-chariot', 102, 'O', 'EP1 - 10', 1, 10, 'Géant de 3 à 4 mètres sans peau dans une armure de métal noir quasiment impénétrable, Chariot est un Ottar qui est très souvent utilisé comme machine de guerre pour poursuivre des cibles bien précise ou semer le trouble dans une ligne ennemi. Cadavre dont on a retiré entièrement la peau et forcé l''intégration de la magie du Sang et de la Nécromancie en même temps, cette créature souffre en permanence et poursuivra vie comme mort sur son chemin.

Possède une force colossale et armé d''une énorme bardiche noire, il est très compliqué de lui faire face quand il est équipé de son énorme armure. La destruction de cette armure est nécessaire pour l''atteindre.

Il est traduit comme une force dont le seul moyen de l''arrêter est de la détruire totalement comme un objet.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23193-23316', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-diable', 'Ottar Diable', 'ottar-diable', 103, 'O', 'EP1 - 10', 1, 10, 'Un individu ayant été exposé simultanément à une quantité excessive de deux vapeurs issues de deux dimensions différentes et incompatibles. Leur présence simultanée dans son organisme provoque un effondrement chakratique unique, les deux influences entrant en conflit et se nourrissant mutuellement.
Plus une personne reste proche de lui, plus elle est exposée aux deux vapeurs et ressent leurs effets. Certaines victimes deviennent progressivement dépendantes de cette énergie, incapables de s''en éloigner malgré les conséquences, tandis que d''autres perdent complètement leur volonté et deviennent les serviteurs de l''Ottar.
Il ne vous forcera pas à le suivre. Il fera en sorte que vous ne puissiez plus vous en passer.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23318-23321', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-empereur', 'Ottar Empereur', 'ottar-empereur', 105, 'O', 'EP1 - 10', 1, 10, 'Créature exclusivement masculine née de dirigeants ou de guerriers dont l’ambition et la mégalomanie ont consumé l’esprit. L’Ottar Empereur surgit toujours dans les nations au faîte de leur puissance, quand leur dirigeant sombre dans l’obsession de la conquête.

Imposant et drapé d’une armure royale déformée, couronné d’un diadème d’os et d’or, il incarne une autorité corrompue et cherche à soumettre tout ce qui vit, quitte à entraîner ses armées et lui-même dans la ruine.

Sa présence seule pousse les esprits faibles à l’obéissance et à la guerre, transformant ses ennemis comme ses alliés en instruments de sa domination. Détruire son corps n’éteint pas sa volonté : tant qu’une nation se bat en son nom, son influence persiste.

Comme d’autres ottars, il est capable de dissimuler son effondrement chakratique pour rester discret.

Tyran incarné, l’Ottar Empereur ne bâtit pas d’empire : il dévore les peuples jusqu’à leur dernier souffle.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23334-23347', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-etoile', 'Ottar Étoile', 'ottar-etoile', 104, 'O', 'EP1 - 10', 1, 10, 'Objet céleste déchu, l’Étoile n’existe que comme influence depuis le ciel. Son énergie violette, mystérieuse et corrosive, pousse les mortels à la folie et les incite à détruire tout ce qui contient du chakra. Les êtres touchés par son pouvoir deviennent ses prophètes, porteurs de la prophétie annonçant son retour.

Le prophète est également le point faible de l’Étoile : en cas de danger, il prend forme physique et devient la représentation incarnée de l’Ottar, concentrant son énergie et sa puissance destructrice. Tant que le prophète demeure intact, l’Étoile conserve son influence omniprésente sur le monde.

De son ciel mourant, elle fendra les esprits et choisira un élu : la fracture commencera.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23323-23330', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-force', 'Ottar Force', 'ottar-force', 106, 'O', 'EP1 - 10', 1, 10, 'Obsession vivante de puissance brute, cet Ottar agit uniquement par instinct et par désir de démontrer sa supériorité. Sa force surhumaine et son endurance hors du commun le rendent presque impossible à arrêter, et il n’hésite pas à éliminer tout concurrent potentiel, même des enfants.

En combat, il cherche avant tout à écraser ses adversaires, défiant toute stratégie ou prudence. Sa folie de puissance le place souvent en conflit avec l’Ambassadeur de la Force.

Il ne connaît ni peur ni raison : seule la force guide ses poings.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23353-23360', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-fou', 'Ottar Fou', 'ottar-fou', 107, 'O', 'EP1 - 10', 1, 10, 'Être dont l’effondrement chakratique a détruit toute perception des règles régissant le monde, le Fou est une abomination imprévisible qui semble incapable de comprendre les notions de logique, de conséquence ou de limite. Son chakra refuse les lois auxquelles tous les autres êtres sont soumis, provoquant autour de lui des phénomènes impossibles et incohérents.
Le Fou est ainsi l''un des Ottars les plus imprévisibles : il ne cherche pas à vaincre les règles du monde, il ne reconnaît simplement plus leur existence.
Il n''est pas imprévisible parce qu''il est fou. Il est imprévisible parce que le monde n''obéit plus aux mêmes règles autour de lui.

Le chaos à l’état brut, à son plus grand extrême.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23362-23368', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-grande-pretresse', 'Ottar Grande prêtresse', 'ottar-grande-pretresse', 108, 'O', 'EP1 - 10', 1, 10, 'Créature exclusivement féminine issue de prêtresses, croisées ou religieuses dont la foi ou la quête de savoir a implosé en un fanatisme absolu. Drapée de haillons religieux et d’un voile monstrueux couvert d''yeux et de glyphes vivants pour cacher son propre visage monstrueux, elle se croit l’incarnation d’une volonté divine.

L’Ottar Grande Prêtresse ne combat pas par la force brute mais par l’influence : ses chants sacrés altèrent l’esprit, forçant ses victimes à s’entretuer ou à se prosterner, tandis qu’elle invoque des manifestations d’ombres et de lumière pour frapper à distance. Plus le combat dure, plus elle se nourrit du désespoir et du chakra de ses cibles.
Elle n’est pas atteignable physiquement ou magiquement, il est nécessaire de trouver ce qui fait que sa foi est autant concentrer, un objet sur elle ou bien une personne, la détruire la rendrait vulnérable.

Comme d’autres ottars, il est capable de dissimuler son effondrement chakratique pour rester discret.

Prophétesse déchue, la Grande Prêtresse ne guide plus : elle asservit les âmes et brise les esprits. Le tout avec une vision déformé de sa divinité.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23370-23381', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-imperatrice', 'Ottar Impératrice', 'ottar-imperatrice', 109, 'O', 'EP1 - 10', 1, 10, 'Créature exclusivement féminine apparaissant chez une dirigeante, une mère ou une figure protectrice dont la compassion et l’empathie ont dépassé toute limite.
Considérée comme une guide suprême par son peuple, l’Impératrice devient progressivement indispensable à ceux qu’elle protège, jusqu’à ce que toute forme d’autonomie disparaisse. Son peuple ne vit plus par lui-même : il vit à travers elle.
Son jugement est cependant profondément déformé. Elle pardonne les fautes les plus graves commises par les femmes qu’elle considère comme ses « enfants », mais se montre impitoyable envers les hommes, condamnant parfois leurs actes les plus insignifiants. Elle ne voit aucune contradiction dans ce traitement : pour elle, protéger les siens justifie tout.
L’Impératrice cherche ainsi à créer un monde où personne ne souffre, quitte à décider à la place de tous de ce qui est bon pour eux.
Sa compassion devient domination, son pardon devient favoritisme et sa protection devient une prison.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23383-23388', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-isole', 'Ottar Isolé', 'ottar-isole', 110, 'O', 'EP1 - 10', 1, 10, 'L’Isolé est un Ottar profondément lié à un lieu qu’il considère comme son territoire. Propriétaire, gardien ou simple occupant, son obsession pour cet endroit est devenue si profonde que toute intrusion est perçue comme une menace existentielle. Lorsqu’il détecte un intrus, il se transforme en chasseur et le traque sans relâche, jusqu’à ce que celui-ci quitte son territoire ou soit détruit.
Même lorsqu’il est contraint de battre en retraite après de nombreux efforts, il revient peu de temps après, entièrement régénéré. Son existence est en réalité liée à un objet dissimulé quelque part dans son territoire, devenu le véritable centre de son obsession. Il est donc essentiel d’écouter ses murmures et ses divagations afin de comprendre ce qu’il cherche désespérément à protéger.
Tant que cet objet demeure intact, l’Isolé est pratiquement immortel. Sa dégradation ou sa destruction rompt cependant son lien avec lui et rend enfin l’Ottar vulnérable. Mais privé de ce qui constituait le dernier fragment de son obsession, il sombre alors dans une hystérie meurtrière et ne cherchera plus qu’à massacrer quiconque se trouve sur son chemin.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23392-23395', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-jugement', 'Ottar Jugement', 'ottar-jugement', 112, 'O', 'EP1 - 10', 1, 10, 'Immense humanoïde dépourvu de visage et armé d’une gigantesque hache de bourreau, l’Ottar Jugement est une incarnation de la condamnation et de la fin. Nul ne sait qui il était avant son effondrement chakratique, son identité ayant totalement disparu derrière la fonction qu’il s’est imposée : être celui qui exécute le jugement.
Contrairement à Justice, le Jugement ne cherche ni à comprendre les crimes ni à déterminer la culpabilité. Il apparaît lorsque, selon lui, le temps du jugement est venu. Il désigne alors ses victimes et les poursuit jusqu’à leur exécution, sans distinction entre coupables et innocents.
Sa nature sans visage semble directement liée à son effondrement : il n''a plus de pensée propre, plus de doute et plus de volonté personnelle. Il n''est plus qu''une fonction, un bourreau incapable de remettre en question l''ordre qu''il s''est lui-même donné. Une fois une sentence prononcée, rien ne peut lui faire changer d''avis.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23405-23408', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-justice', 'Ottar Justice', 'ottar-justice', 111, 'O', 'EP1 - 10', 1, 10, 'Figure d’une jeune femme aveugle portant une balance et une épée, l’Ottar Justice est né d’une personne dont l’obsession pour l’équité et le châtiment a fini par consumer toute raison. Pour elle, aucune faute ne peut rester impunie, aussi insignifiante soit-elle. Un mensonge, un vol, une insulte ou même une simple transgression de loi peuvent suffire à condamner quelqu’un à mort.
Privée de toute capacité à considérer le contexte, le remords ou le pardon, elle ne juge plus les individus mais uniquement leurs actes. Sa balance ne cherche pas à déterminer si quelqu’un mérite réellement de mourir : elle ne fait que constater la faute et réclamer son prix. Elle peut ainsi condamner aussi bien un criminel sanguinaire qu''un enfant ayant commis une petite désobéissance.
Son aveuglement est devenu une manifestation de son effondrement chakratique : elle ne voit plus le monde, seulement ce qu''elle considère comme juste. Quiconque tente de s''opposer à son jugement devient à son tour coupable d''avoir entravé la justice.
La loi à l’état brut, à son plus grand extrême.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23399-23403', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-lune', 'Ottar Lune', 'ottar-lune', 113, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Lune prend la forme d’une île mystérieuse et nomade, errant à travers les océans sans jamais suivre de trajectoire connue. L’île apparaît principalement aux marins égarés et les attire jusqu’à ses côtes, où ceux qui y échouent sont contraints de participer à d’étranges épreuves dont nul ne connaît véritablement la nature.
Ceux qui parviennent à survivre sont finalement relâchés en mer, mais l’Ottar efface entièrement de leur esprit le souvenir de son existence. Ils ne se souviennent ni de l’île, ni des épreuves, ni même de la manière dont ils ont survécu. Il subsiste toutefois une anomalie impossible à expliquer : un tatouage en forme de lune apparaît sur leur corps, marquant ceux qui ont traversé les épreuves de l’Ottar et en sont ressortis vivants.
L’Ottar Lune est particulièrement dangereux car sa position est impossible à prévoir et ses survivants eux-mêmes ignorent qu’ils ont été confrontés à lui. Certains peuvent ainsi porter depuis des années la marque de la Lune sans jamais comprendre son origine.
Comme d’autres ottars, il est capable de dissimuler son effondrement chakratique pour rester discret.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23412-23416', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-magicien', 'Ottar Magicien', 'ottar-magicien', 114, 'O', 'EP1 - 10', 1, 10, 'Le Magicien est une créature humanoïde dont la peau semble faite de métal poli, parcourue de fissures lumineuses où le chakra bouillonne et s’échappe en pulsations constantes. Il est l’incarnation de la soif de puissance et de connaissance, d’une obsession qui a consumé son esprit. Ce sont généralement des individus qui ont cherché à dépasser les limites de leur chakra, à manipuler la magie dans toutes ses formes, ou à expérimenter sur eux-mêmes et le monde jusqu’à perdre toute raison.
Chaque geste du Magicien est une démonstration de contrôle absolu sur son énergie, mais aussi de sa folie : il maîtrise le potentiel illimité sans avoir le défaut de la faiblesse physique. Sa présence seule est un danger, car elle corrompt et perturbe tout flux de magie à proximité.
Il ou elle a voulu tout comprendre, tout contrôler, tout manipuler… et la folie est devenue son pouvoir.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23420-23423', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-monde', 'Ottar Monde', 'ottar-monde', 115, 'O', 'EP1 - 10', 1, 10, 'Surnommé le « Divinicide », Monde est considéré comme l’Ottar le plus puissant jamais observé. Il représente une menace si considérable que même les Dieux craignent son apparition, car il serait capable de les tuer.
L’Ottar Monde apparaît parfois lorsqu’un événement d’une ampleur catastrophique frappe le monde et provoque la mort de millions d’êtres. Parmi tous les morts, un seul se distingue : son chakra s’effondre et le transforme en l’Ottar Monde, qui devient le général d’une gigantesque armée composée des défunts de la catastrophe.
Cette armée ne cherche ni vengeance ni survie. Elle poursuit un objectif unique : conquérir les domaines des Dieux, exterminer les divinités et prendre leur place dans l’ordre du monde. Chaque mort supplémentaire peut ainsi devenir un nouveau soldat de son armée.
L’apparition du Monde est donc considérée comme une catastrophe à l’échelle planétaire. Là où il apparaît, les morts ne sont plus seulement une conséquence du désastre : ils deviennent son armée.
Lorsque le monde connaîtra sa plus grande tragédie, l’un de ses morts se relèvera pour tuer ses Dieux.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23425-23430', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-mort', 'Ottar Mort', 'ottar-mort', 116, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Mort apparaît lorsqu’un être confronté à la mort brutale d’un proche refuse d’accepter sa disparition et laisse sa haine prendre le dessus. Dans un rituel destiné à obtenir la puissance nécessaire pour accomplir sa vengeance, son chakra s’effondre et transforme son corps en une créature morte-vivante.
Mais la véritable horreur de l’Ottar réside dans le lien qui unit les deux êtres. Si la moitié devenue morte-vivante est détruite, la moitié morte est immédiatement ramenée à la vie, animée par la même haine et le même désir de vengeance. À son tour, sa mort provoquera la résurrection de son autre moitié.
La mort ne fait ainsi que déplacer le problème. Chaque tentative de destruction inverse le rôle des deux êtres et perpétue le cycle, faisant de l’Ottar une abomination qui semble incapable de connaître une véritable fin.
Aucun moyen de mettre définitivement un terme à ce cycle n’est connu à ce jour, à l’exception du bannissement de l’Ottar.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23432-23436', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-pendu', 'Ottar Pendu', 'ottar-pendu', 117, 'O', 'EP1 - 10', 1, 10, 'Fusion tragique d’un être humanoïde et d’un arbre dégénéré, le Pendu semble immobile, suspendu dans un sommeil profond. Mais son chakra alimente la forêt qui s’étend autour de lui, ses racines et branches corrompues étouffant tout sur leur passage.

Autour de lui, des cultistes mi-arbres mi-humanoïdes veillent, défendant le Pendu avec une ferveur fanatique. Toute tentative de destruction de l’Ottar doit passer par le Pendu qui a fusionné avec l’arbre, car le corps et la forêt sont intimement liés.

Suspendu entre vie et mort, le Pendu fait croître sa forêt sur les os de ses victimes.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23440-23447', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-roue-du-destin', 'Ottar Roue du Destin', 'ottar-roue-du-destin', 118, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Roue du Destin se dissimule parmi les marchands, les voyageurs et les voyants, proposant ses services à ceux qui souhaitent connaître leur avenir. Ses prédictions sont d’une précision déconcertante, mais concernent généralement des événements sans grande importance : une rencontre heureuse, une bonne fortune ou au contraire une mésaventure sans conséquence.
La véritable nature de son pouvoir est cependant bien plus inquiétante. La Roue du Destin ne se contente pas de prédire l’avenir : elle est capable d’influencer les événements qui doivent bientôt se produire, faisant basculer la chance en faveur ou en défaveur de personnes choisies. Nul ne sait jamais qui sera touché par ses caprices.
Il arrive cependant qu’une de ses visions annonce la mort prochaine d’un individu. Dans ce cas, la prédiction n’est pas une simple possibilité : l’Ottar devient lui-même l''instrument du destin et viendra personnellement accomplir la mort qu’il a annoncée.
Comme d’autres ottars, il est capable de dissimuler son effondrement chakratique pour rester discret.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23449-23453', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-soleil', 'Ottar Soleil', 'ottar-soleil', 119, 'O', 'EP1 - 10', 1, 10, 'L’Ottar Soleil prend la forme d’un bâtiment banal apparaissant dans des lieux où une ou plusieurs personnes cherchent à s’abriter du froid, de la pluie ou de la neige. Il peut également apparaître au cœur même des villes, sans que personne ne remarque son arrivée. Son intérieur semble parfaitement accueillant : un feu crépite dans la cheminée, de la nourriture est disponible et tout est fait pour offrir à ses occupants un sentiment de sécurité et de confort.
Mais lorsque ses occupants sont suffisamment nombreux ou que l’Ottar décide de se révéler, tout s’effondre. Les murs, les meubles et les portes disparaissent pour laisser place à une immense pièce circulaire entièrement recouverte de cendres. Au plafond apparaît alors une fresque représentant un soleil monstrueux dévorant des êtres vivants. Et c’est ainsi que tout commence … ce même soleil représenter commence à lentement dévorer les victimes piégées.
L’Ottar Soleil est particulièrement difficile à vaincre car sa véritable nature se confond avec la maison elle-même. Il est donc nécessaire de découvrir le point faible caché de cette structure vivante avant de pouvoir la détruire. Et bien entendu avant tout ça, il faut abattre les Cultistes.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23457-23460', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-temperence', 'Ottar Tempérence', 'ottar-temperence', 120, 'O', 'EP1 - 10', 1, 10, 'Tempérance est une créature possédant deux âmes ou plus dans un même corps, plongée dans un conflit intérieur constant. Ce désaccord libère une énergie chaotique et incontrôlable, rendant la créature capable d’utiliser simultanément plusieurs magies. Au fil du temps, les différentes âmes modifient le corps de la créature : couleur de peau, corpulence et traits changent, traduisant visuellement le déséquilibre.

Tant que le conflit persiste, Tempérance continue à se transformer, risquant de devenir complètement difforme et de s’effondrer sur lui-même. Il est recommandé de le détruire rapidement avant que sa dégénérescence magique n’affecte tout autour.

Deux âmes, une seule enveloppe : tant que le conflit brûle, le monde autour subit ses flammes invisibles.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23462-23469', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ottar-tour', 'Ottar Tour', 'ottar-tour', 121, 'O', 'EP1 - 10', 1, 10, 'Incarnation de l’effondrement, l’Ottar Tour n’est pas un simple être : c’est une abomination chakratique dégénérée, mi-machine, mi-organique, née de l’hubris des mortels. Plus qu’un adversaire, il est une catastrophe qui abat tout ce qui est érigé — villes, forteresses, nations.

Au cœur de cette abomination se trouve une personne dont la soif de destruction a fait imploser son chakra. Son corps est enfermé dans une Armure liée, une carapace impénétrable par des moyens conventionnels. Seules les Armes liées peuvent la percer.

Si l’Armure liée n’est pas détruite, l’Ottar révèle sa véritable forme : une tour gigantesque, vivante, qui détruit et stérilise tout autour de lui. L’Armure liée reste son unique point faible, au centre de la tour. Seuls les plus fous ou déterminés peuvent atteindre ce cœur et mettre fin à la menace.

La Tour n’a d’autre objectif que de renverser tout ce qui est construit, sans distinction entre ses créateurs et ses victimes. Son apparition est un mauvais présage, annonçant la chute imminente des fondations d’une société.

La Tour est un cataclysme : elle ne combat pas, elle renverse. Elle fait table rase, et fait prendre un nouveau départ.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 23475-23488', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/ours-garou', 'Ours-garou', 'ours-garou', 122, 'O', 'EP1 - 10', 1, 10, 'L’Ours-Garou est un démon, une abomination née d’une exposition prolongée au nuage de Kcirevam. Jadis un Orios, cette créature a été déformée, corrompue jusqu’à perdre toute raison. Sa musculature a doublé, sa fourrure s’est épaissie, et sa taille dépasse désormais celle des plus grands Orios. Sa tête, autrefois humanoïde, est devenue celle d’un ours monstrueux — symbole de la sauvagerie totale qui l’habite désormais.
Il est une incarnation de la force brute. Il ne cherche ni stratégie ni subtilité : son instinct le pousse à dominer par la violence pure. Peu de démons peuvent rivaliser avec lui sur le plan physique. Certains ont été vus maniant d’énormes pioches de combat d’une seule main, mais la plupart préfèrent se battre avec leurs griffes acérées ou leurs mâchoires capables de broyer les os les plus solides.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 23490-23879', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/pigeon-foudroyant', 'Pigeon foudroyant', 'pigeon-foudroyant', 123, 'P', 'EP1', 1, 1, 'Le Pigeon foudroyant s''est élevé au-dessus des autres columbiformes en transmettant ses habilités électrisantes à ses descendants. Les rumeurs parlent d''un pigeon ayant eu l''idée brillante d''entamer sa migration en passant au-dessus du Plateau Tonnerre. Évidemment, l''inévitable se produisit et la foudre a frappé le rat des cieux, mais contre toutes attentes : il survécu à l''impact. Après cet événement insolite, les pouvoirs de Volt l''envahirent et devint celui que l''on connaît aujourd''hui : un pigeon survolté près à surpasser sa réputation de nuisible.
La rumeur ne dit pas cependant par quel miracle il eut réellement l''acquisition de ses pouvoirs.

Les ornithologues rationnels vous diront que rien de tout cela n''est vrai mais les maverickiens préfèrent l''idée que le Dieu de la Foudre, pourtant sérieux et froid, s''esclaffa pour la première fois depuis des siècles devant ce spectacle pathétique. En récompense, il offre une seconde chance au volatile sans cervelle. Probablement le seul mythe auquel on veut vraiment croire.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 23886-24062', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/potirobuste', 'Potirobuste', 'potirobuste', 124, 'P', 'EP5', 5, 5, 'Le Potirobuste est une variante martiale des mystérieux Potimen, ces épouvantails animés à tête de potiron creusé dont l’intérieur brûle d’une flamme colorée. Son corps, plus épais que les autres, est constitué de bottes de paille solidement liées, renforcées par des pièces de bois et de métal rudimentaires. Contrairement aux autres Potimens, le Potirobuste adopte une stature imposante et guerrière, se tenant droit au milieu des champs de blé qu’il protège. Sa flamme, d’un rouge ardent, éclaire l’intérieur de sa tête sculptée et pulse au rythme de sa colère.
Comme tous les siens, il garde les gigantesques champs de blé et attaque sans hésitation tout intrus pénétrant son territoire. Pourtant, à la fin de l’été et au début de l’automne, les Potimen cessent toute hostilité et laissent la récolte se faire en paix, un mystère que nul érudit n’a encore percé. Cette trêve saisonnière contraste avec la brutalité dont ils font preuve le reste de l’année.
Armé d’une grande fourche, le Potirobuste combat avec la discipline d’un lancier et la férocité d’un martial. Il mise sur sa force brute et sur des élans de rage qui renforcent ses assauts. Sa flamme rouge témoigne de sa maîtrise conjointe de la magie du Feu et de la Lumière, qu’il canalise dans ses attaques pour brûler, repousser ou purifier.', 'Champs', NULL, 'monstres', 'Bestiaire 2.0 › lignes 24068-24204', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/potirodeur', 'Potirodeur', 'potirodeur', 125, 'P', 'EP5', 5, 5, 'Le Potirodeur est l’ombre silencieuse des champs dorés, une variante discrète des mystérieux Potimen, ces épouvantails animés à tête de potiron creusé dont l’intérieur brûle d’une flamme colorée. Son corps de paille est plus fin, plus souple, souvent enveloppé de tissus sombres qui lui permettent de se fondre entre les hautes tiges de blé. Dans sa tête sculptée verte vacille une flamme verte, symbole de sa maîtrise du Vent et de la Lumière.
Comme tous les Potimen, il protège les gigantesques champs et attaque tout intrus imprudent, sauf durant la mystérieuse période de fin d’été et début d’automne où toute hostilité cesse pour permettre la récolte. Mais contrairement aux autres variantes plus visibles, le Potirodeur préfère ne pas se montrer. Il observe, attend, et choisit le moment parfait pour intervenir.
Armé de deux dagues et d’un arc long, il adopte un style de combat proche d’un Tueur Bimane, privilégiant les attaques sournoises et les frappes rapides. Il surgit des ombres du champ pour porter un coup précis avant de disparaître aussitôt, utilisant la magie du Vent pour accélérer ses déplacements et celle de la Lumière pour troubler la perception de ses cibles.', 'Champs', NULL, 'monstres', 'Bestiaire 2.0 › lignes 24208-24351', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/potironcier', 'Potironcier', 'potironcier', 126, 'P', 'EP5', 5, 5, 'Le Potironcier est une incarnation érudite des mystérieux Potimen, ces épouvantails animés à tête de potiron creusé dont l’intérieur brûle d’une flamme colorée. Son corps de paille est dissimulé sous une longue cape sombre qui ondule au vent des champs qu’il protège. À l’intérieur de sa tête blanche sculptée danse une flamme blanche éclatante, pure et stable, symbole de sa maîtrise de la magie de l’Arcane et de la Lumière.
Comme tous les siens, le Potironcier garde les immenses champs de blé et attaque sans hésitation les intrus. Pourtant, à la fin de l’été et au début de l’automne, lui et ses semblables suspendent toute hostilité pour laisser place à la récolte géante. Nul ne sait pourquoi cette trêve saisonnière existe, ni quelle volonté mystérieuse régit leur comportement.
Contrairement au Potirobuste, il ne mise pas sur la force physique mais sur une réserve de Chakra conséquente qu’il canalise avec précision. Comparable à un Mage et un Ocultomancien, il dissimule sous sa cape un bâton magique de l’arcane qu’il utilise pour projeter des sorts. Ses attaques magiques sont précises, tranchantes et méthodiques, frappant à distance avec une froide détermination.', 'Champs', NULL, 'monstres', 'Bestiaire 2.0 › lignes 24353-24489', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/presque-ottar', '“Presque-Ottar”', 'presque-ottar', 100, 'O', 'EP1 - 10', 1, 10, 'Le Presque-Ottar est une créature en pleine transition vers sa transformation totale en Ottar. Son apparence varie considérablement selon la ou les magies qui l’habitent : ses caractéristiques physiques, sa morphologie et même certaines parties de son corps peuvent changer selon qu’il est lié à une seule magie ou à deux. Dans tous les cas, ces influences magiques se manifestent sous une forme exagérée, difforme, voire grotesque, donnant naissance à une créature dont le corps semble incapable de contenir correctement le pouvoir qui l’habite.
Un Presque-Ottar représente ainsi une vision déformée de la magie qu’il possède. Il ne s’agit pourtant que d’un état temporaire : si la créature survit suffisamment longtemps, son corps finira par achever sa transformation et devenir un véritable Ottar.
Pour cette raison, il est admis par tous les peuples connaissant leur existence qu’un Presque-Ottar ne doit en aucun cas rester en vie. Même lorsqu’il semble encore maîtrisable, personne ne peut prévoir comment sa transformation évoluera ni ce qu’il deviendra une fois celle-ci achevée.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 22742-23172', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/radrak-frenetique', 'Radrak frénétique', 'radrak-frenetique', 127, 'R', 'EP10', 10, 10, 'Le Radrak frénétique est un quadrupède colossal atteignant près de 3 mètres de hauteur, véritable montagne vivante que nul ne devrait sous-estimer. Son corps massif est recouvert d’écailles épaisses, dures comme la pierre, et surmonté de quatre cornes puissantes encadrant une mâchoire garnie de rangées de dents irrégulières. Pourtant, sa caractéristique la plus remarquable demeure sa nature d’anti-magie : sa peau est recouverte d’une fine couche naturelle de maverium. Face à lui, les mages deviennent presque inutiles.
Malgré son apparence terrifiante, le Radrak est un herbivore vorace. Il se nourrit principalement de grands arbres, dévorant feuilles, branches, fruits et parfois même le tronc entier rappelant celle d’un castor géant. Son passage laisse derrière lui des clairières ravagées et des forêts clairsemées. Sa taille et sa résistance naturelle lui assurent très peu de prédateurs, ce qui en fait un dominant incontesté de son environnement.
Cependant, cette puissance colossale s’accompagne de faiblesses notables. Sa corpulence le rend lent et difficile à manœuvrer, ce qui le rend vulnérable aux attaques à distance, aux adversaires aériens ou aux créatures plus petites capables de l’harceler et de l’épuiser. Les parasites et les meutes organisées représentent également une menace réelle. Et malgré tout ça, sa carapace possède une faiblesse qui est l’acide, l’acide ronge efficacement sa peau et les rares sortilèges qui infligent des dégâts d’acide fonctionnent sur lui.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 24492-24745', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/rat', 'Rat', 'rat', 128, 'R', 'EP1', 1, 1, 'Le Rat est une créature commune des ruelles, des souterrains et des champs abandonnés. Plus gros que les rongeurs ordinaires, il peut atteindre la taille d’un chien, avec un corps nerveux, un pelage terne et des incisives particulièrement développées. Individuellement faible et fragile, il mise sur la rapidité et le nombre pour survivre dans les environnements hostiles.
La plupart des rats ne représentent qu’une nuisance mineure. Cependant, certains spécimens plus anciens ou exposés à des énergies obscures développent une affinité inquiétante avec la nécromancie. Ces individus présentent des yeux verts profonds brillants, une chair partiellement nécrosée ou une agressivité anormale. Bien qu’ils restent physiquement peu impressionnants, leur morsure peut infliger le poison.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 24749-24959', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/salithre', 'Salithre', 'salithre', 129, 'S', 'EP2', 2, 2, 'Un mélange un peu grossier entre une huître et un crabe, ce crustacé d’environ 1m30 se promène sur les plages à la recherche de sel et de roche à dévorer. Son régime alimentaire influence la solidité de sa carapace et le rend très solide.

Ils sont parfois recherchés par les chercheurs de trésor car certains spécimens possèdent de belles perles, ces dernières ont une grande valeur pour ceux qui travaillent les gemmes précieuses ou même les utilisateurs de l’arcane. Bien qu’il y ai pas de grosse différence de perle qu’on retrouve dans des huîtres normaux, elles sont plus grosses donc plus chères.

On le retrouve partout où il y a des plages mais l’endroit où ils se réunissent le plus c’est la grande plage blanche où se trouve la grande mine de sel et le temple du sel dans Engrevua.', 'Plage, Eau', NULL, 'monstres', 'Bestiaire 2.0 › lignes 24970-25132', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/sanglier', 'Sanglier', 'sanglier', 130, 'S', 'EP2', 2, 2, 'Les sangliers sont des omnivores bien plus agressifs et dangereux que leurs cousins apprivoisés. On les rencontre assez souvent en forêts mais ils vivent également sous les climats tropicaux.
Le naturel têtu des sangliers et leur habitude de manger tout, même les os, en font des compagnons parfaits pour certaines créatures.

Lieux de rencontres : forêts tempérées et tropicales.', NULL, NULL, 'monstres', 'Bestiaire 2.0 › lignes 25136-25286', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/saurotudo', 'Saurotudo', 'saurotudo', 131, 'S', 'EP3', 3, 3, 'Le Saurotudo est une créature massive et paisible, mesurant près de 3 mètres de haut pour 4 mètres et demi de long. Son corps est recouvert d''une carapace semblable à de la roche, formée de plaques épaisses qui le protègent des menaces. Son corps est parfaitement adapté pour la vie dans les marécages. On peut souvent le voir s’enfoncer dans les eaux boueuses des marécages, ne laissant dépasser que son dos rocailleux.
Le Saurotudo est lié aux magies de Terre et d’Eau, ce qui lui permet de détecter les courants souterrains ou les zones humides instables. Il est particulièrement sensible aux variations de la qualité de l’eau : les marais chargés de brais ou de substances épaisses et toxiques le dérangent, le poussant à migrer vers des zones plus pures, sa présence dans un marais permet de savoir si ce dernier est en “bonne santé”.
Cette créature est aussi parfois apprivoisée dans la région de Mrode, notamment pour sa force naturelle, ce qui le rend idéal pour le transport de marchandise, ou alors tout simplement comme transport dans les zones très marécageuses qu’on peut retrouver dans cette région. Son caractère paisible fait qu’elle est appréciée et protégée contre les braconniers.', 'Marais, Forêt, Plaine', NULL, 'monstres', 'Bestiaire 2.0 › lignes 25288-25358', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/soldat-de-fer', 'Soldat de fer', 'soldat-de-fer', 132, 'S', 'EP4', 4, 4, 'Le Soldat de Fer est une abomination née des mystérieuses Terres Grises, au cœur du continent de Mrode. Son origine demeure incertaine, mais de nombreux érudits soupçonnent un cataclysme ancien mêlant la magie de la Terre et celle du Vide, fusionnant matière minérale et néant en une forme instable et hostile. Son corps est constitué d’un métal sombre et liquide, perpétuellement en mouvement, prenant une silhouette humanoïde lisse et sans visage, dépourvue de traits.
Ces créatures émergent des lacs de métal liquide qui parsèment les Terres Grises. Lorsqu’elles ne chassent pas, elles s’y fondent totalement, ne faisant plus qu’un avec la masse liquide, cherchant lentement à s’étendre et à engloutir leur environnement. À la moindre intrusion, elles surgissent en silence, leur corps se solidifiant partiellement pour adopter une forme de combat. Leur présence déforme légèrement le sol, comme si la réalité peinait à contenir leur substance.
Chaque Soldat de Fer possède une arme organique, extension directe de son propre corps métallique. Cette arme se façonne et se durcit selon les besoins du combat, frappant avec une précision implacable. À distance, un œil unique se matérialise brièvement sur leur tête lisse pour projeter un rayon de métal condensé, capable de perforer armures et défenses magiques. Plus inquiétant encore, ils peuvent imprégner leur lame d’un élément, adaptant leurs attaques pour contourner les résistances de leurs adversaires. Affronter un Soldat de Fer revient à combattre une arme vivante, froide, implacable, silencieuse… et inlassablement déterminée à éliminer tout intrus.', 'Terres grises, ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 25362-25538', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/solecorche', 'Solécorché', 'solecorche', 133, 'S', 'EP7', 7, 7, 'Le Solécorché est un cadavre réanimé non pas par la magie, mais par une lumière sacrée corrompue. Autrefois purificatrice, cette lumière s’est infiltrée dans le corps en le maintenant en vie… mais en consumant peu à peu son enveloppe. Résultat : un non-mort brillant, mais en agonie permanente, brûlé de l’intérieur. Cette lumière qui le brûle lui donne beaucoup de puissance mais il reste que peu de temps sur le champ de bataille. Il se bat avec une lame qui semble être entièrement faite de lumière et qui semble le brûlé lui-même.

Cette lumière brûlante s’active uniquement quand il est dans une zone où il y a trop de lumière ou lorsqu’il est en combat.', 'Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 25540-25719', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/squelette', 'Squelette', 'squelette', 134, 'S', 'EP1', 1, 1, 'Les squelettes sont des serviteurs du mal animés par une énergie nécromantique. Leur ossature blanche, parfois maculée de restes de chair desséchée ou de chaînes rouillées, trahit leur origine morbide. Leur absence de conscience et de peur les pousse à affronter tout adversaire sans aucune retenue, mais leur carcasse fragile se fait très vite réduire en miettes par l’ennemi.', 'Ruines, Cimetière, Plaine, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 25731-25972', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/squelette-archer', 'Squelette archer', 'squelette-archer', 136, 'S', 'EP2', 2, 2, 'Armés d''arcs rudimentaires, les Archers Squelettes s''attaquent inlassablement à tout ce qui vit. Leur totale absence de conscience leur permet de se lancer au combat sans réfléchir et de frapper en premier, mais leurs fragiles carcasses sont facilement réduites en pièces par l''ennemi.', 'Ruines, Cimetière, Plaine, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 26154-26337', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/squelette-de-pierre', 'Squelette de pierre', 'squelette-de-pierre', 135, 'S', 'EP6', 6, 6, 'Victime de la malédiction de la Pierre, une maladie d''origine d''une île éloignée. Ce pauvre être est arrivé au stade final où son corps entier s''est ossifié pour devenir un être totalement fait d''os, seul persiste ses yeux ainsi que son cerveau (qui est touché lui aussi pour lui laisser le minimum).
Son corps entièrement rigide fait de lui un ennemi qui est lent mais qui est très résistant.', 'Montagne, Neige, Forêt froide, Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 25976-26150', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/squelette-mauvais', 'Squelette mauvais', 'squelette-mauvais', 137, 'S', 'EP10', 10, 10, 'L''un des Mort-Vivants les plus puissant jamais vue dans Maverick, en plus d''avoir une force surnaturel, il maîtrise sans problème la magie de la Foudre et de l''Ombre. C''est un squelette humanoïde avec des muscles, sauf à la tête, de grandes griffes aux mains et des cornes grandes.
Ce squelette possède des origines assez variées mais il s''agit le plus souvent d''un personnage important ayant eu un rôle central au sein d''une communauté (empereur, roi, maire, chef, etc...) avec beaucoup de responsabilité. Mais un échec cuisant a emporté lui et son peuple, il a rejeté toutes ses convictions pour ramener son peuple par sa seule puissance et volonté seules, on soupçonne qu''une force extérieure a aidé ce puissant mort-vivant, surtout que cet être est capable de faucher les âmes comme le ferait un nécromancien.', 'Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 26341-26536', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/squelette-venin', 'Squelette venin', 'squelette-venin', 138, 'S', 'EP3', 3, 3, 'Le Squelette Venin est un non-mort dont la moelle osseuse est entièrement saturée de poison, teintant ses os de nuances verdâtres et faisant parfois suinter un venin corrosif.
Il combat principalement à l’aide de griffes osseuses qu’il manie avec une grande aisance, les plus fort se battent avec deux dagues dont les lames sont d’un vert effrayant. Chaque entaille inocule le poison directement dans le corps de la victime, provoquant un affaiblissement progressif. Le Squelette Venin privilégie les affrontements prolongés, laissant le poison faire son œuvre plutôt que de chercher une mise à mort immédiate.
En complément, il maîtrise certains sorts de la nécromancie, capables d’empoisonner à distance ou de contaminer une zone entière. Souvent utilisé comme gardien ou comme arme par des nécromanciens sans scrupule.', 'Ruines, Marais, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 26546-26734', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/velue', 'Velue', 'velue', 139, 'V', 'EP1-10', 1, 10, 'La Velue est la forme démoniaque et chaotique des Drakos, une mutation monstrueuse née à cause d’une sur-exposition au Nuage de Kcirevam. Son corps draconique est recouvert d''écailles qui croissent en permanence, se transformant peu à peu en de longs pics acérés recouvrant son dos, sa queue et ses membres. La couleur de ces excroissances varie selon la magie qu''elle maîtrise, faisant de chaque Velue une incarnation vivante de son élément. Plus elle vieillit, plus sa silhouette devient hérissée de pointes, la rendant aussi terrifiante qu''imposante.
Cette armure naturelle lui confère une résistance supplémentaire. Lorsqu''ils atteignent une taille suffisante, la Velue peut les projeter violemment en cône sur ses adversaires, transformant son propre corps en une véritable batterie de projectiles. Elle est également capable de libérer un souffle élémentaire correspondant à sa magie.
Les Velues les plus puissantes sont réputées pour leur témérité suicidaire. Lorsqu''elles jugent leur proie suffisamment dangereuse, elles s''élancent dans une charge dévastatrice, ignorant tout instinct de préservation. Elles percutent leur cible avec une force colossale, n''hésitant pas à traverser arbres, murailles ou rochers pour l''atteindre. L''impact est capable de ravager une ligne entière d''ennemis, mais cette attaque laisse la créature momentanément désorientée et totalement vulnérable pendant quelques instants, offrant une rare occasion de contre-attaquer à ceux qui survivent à sa furie.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 26743-27477', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/voromorphe', 'Voromorphe', 'voromorphe', 140, 'V', 'EP5', 5, 5, 'Le Voromorphe est une créature carnivore, considérée comme l’un des prédateurs a ne pas sous-estimé. Sa particularité – et la source de son appellation – réside dans sa capacité d’adaptation élémentaire. Contrairement aux autres monstres liés à un seul élément, le Voromorphe assimile l’essence du milieu où il vit et s’y adapte totalement, jusqu’à métamorphoser son corps. Cette adaptation n’est pas instantanée, il lui faut plusieurs mois pour réussir à changer son corps, ce lap de temps rend la créature assez vulnérable, d’où son changement de comportement où il se fait plus discret le temps qu’il faut.

Bien qu’intelligent, le Voromorphe agit avant tout par instinct de survie et de domination. Son territoire peut s’étendre sur plusieurs dizaines de kilomètres, qu’il patrouille avec une régularité implacable.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 27483-27681', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/zombi', 'Zombi', 'zombi', 141, 'Z', 'EP1', 1, 1, 'Les zombis sont des cadavres en putréfaction ambulants qui chasse pour se nourrir de la vie qu’ils haïssent tant. Ce sont des créatures assez solides qui ne ressentent pas la douleur et qui mordent violemment leur victime avec leur morsure.

Ils sont souvent utilisés par les nécromanciens pour exterminer leur ennemi.', 'Ruines, Cimetière, Plaine, Forêt', NULL, 'monstres', 'Bestiaire 2.0 › lignes 27692-27864', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/zombi-soldat', 'Zombi soldat', 'zombi-soldat', 142, 'Z', 'EP2', 2, 2, 'Le Zombi Soldat est un cadavre putréfié relevé par la nécromancie dans un but strictement militaire. Animé par une volonté étrangère, il avance sans peur ni douleur, répandant autour de lui une odeur de mort et de maladie.
Bien que lent et maladroit, le Zombi Soldat compense par son équipement de guerre : une armure rouillée encore fonctionnelle et une lourde hache de bataille qu’il manie avec une brutalité primitive. Chaque coup porté est imprévisible et peut infliger un poison ou une infection, transformant même une blessure mineure en menace mortelle à long terme.
Toujours dans une posture agressive, le Zombi Soldat est incapable de véritablement parer les attaques, mais il peut intercepter un coup destiné à un allié proche, utilisant son propre corps comme bouclier. Cette capacité en fait un excellent fantassin sacrificiel, conçu pour épuiser l’ennemi et ouvrir la voie à des troupes plus dangereuses.', 'Ici et là', NULL, 'monstres', 'Bestiaire 2.0 › lignes 27868-28049', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/zombinox', 'Zombinox', 'zombinox', 143, 'Z', 'EP4', 4, 4, 'Le Zombinox est une créature modifiée et est très difficile à tuer à cause de sa robustesse hors norme.', 'Ruines, Laboratoire', NULL, 'monstres', 'Bestiaire 2.0 › lignes 28055-28207', NULL, NULL, NULL, NULL);
INSERT INTO monstre_espece (id, nom, nom_cle, ordre, lettre, ep_brut, ep_min, ep_max, description, lieu_brut, complement, origine, source_ref, portrait, portrait_x, portrait_y, portrait_zoom) VALUES ('monstres/zompi', 'Zompi', 'zompi', 144, 'Z', 'EP3', 3, 3, 'Le Zompi est un cadavre réanimé par un champignon parasite d’origine inconnue. Ce dernier s’empare du système nerveux et musculaire de son hôte mort, le faisant bouger avec des gestes saccadés, comme tiré par des fils invisibles. Le champignon prolifère à travers le corps en formant des excroissances mycosiques : des chapeaux difformes, des amas de spores sur le dos, et des filaments qui s’échappent des yeux, de la bouche ou des plaies ouvertes. Sa peau en décomposition est percée de racines fongiques qui le maintiennent debout bien après la mort.', 'Marais, Ruines', NULL, 'monstres', 'Bestiaire 2.0 › lignes 28213-28407', NULL, NULL, NULL, NULL);
